window.CHAPTER_DATA["ch17"]={"id": "ch17", "num": 17, "part": "הוצאה", "title": "שנים שעשאוה", "paras": [{"s": "h2", "h": "שנים שעשאוה"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1017\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">1\u003c/sup>\u003cspan class=\"ca\" data-c=\"1017\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">א. בירור גדר פטור דשנים שעשאוה\u003c/span>"}, {"s": "h7", "h": "דיני פטור וחיוב הנלמדים מפרשת חטאת - עוקר ומניח, זה וזה יכולין, ואינן יכולין במעשה סתם"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"325\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">2\u003c/sup>\u003cspan class=\"ca\" data-c=\"325\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ואם נפש אחת תחטא בשגגה מעם הארץ בעשתה אחת ממצות ד' אשר לא תעשינה ואשם.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"326\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">3\u003c/sup>\u003cspan class=\"ca\" data-c=\"326\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">הנה מצאנו בפסוק זה דינים הנוגעים לחיוב חטאת במלאכות שבת בכמה אנפין, דלמדו מזה דין דזה עוקר וזה מניח פטור, ולמדו בזה יכול וזה יכול דהוה מח' ר\"מ ור\"י, ובזה אינו יכול וזה אינו יכול דהוה מח' ר\"י ור\"ש, ומלבד זה מצאנו דזה יכול וזה אינו יכול כ\"ע מודו דחייב זה דיכול, וזה דאינו יכול פטור דהוה מסייע, וכן מצאנו שלמדו מזה דחייב רק מי שעשה כולה ולא מקצתה, ויש לחלק גדרי מח' זו, וכמש\"כ לעיל דדינים שנאמרו בפרשת חטאת, גדרם הוא במעשה סתם ולא ביחס לשם מלאכה דאית ביה.\u003c/span>"}, {"s": "h7", "h": "גדר עשייה דעוקר ומניח - חילוקה מכתיבה שתוצאת המעשה הוי דבר מוגמר בפני עצמו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"327\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">4\u003c/sup>\u003cspan class=\"ca\" data-c=\"327\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה בזה עוקר וזה מניח הרי שכל אחד עשה חלק מן המלאכה, וכתבו בתוס' דלגבי שאר מלאכות כמו כתיבה, אי כתב אחד אות אחת וכתב שני אות שניה, אין צריך פסוק אלא רק להוצאה דאיכא להוצאה והכנסה בחד, והו\"א דלחייב, אפילו ליכא הנחה, והיינו, דמלאכת הוצאה אין היא כשאר מלאכות שיש בעשיית חלק מהם חסרון בשיעור המלאכה, וזה חסרון במלאכת מחשבת שאין ראוי להיחשב בפחות מכשיעור, וכיון דכתיבה ועוד מלאכות אין בהם אלא יצירת הדבר המוגמר (בכתיבה היינו, הדבר הכתוב) הרי שודאי דבכתיבת אות אחת נגמר המלאכה דאות אחת, וא\"כ מאי דלא מחייב אלא ע\"י אות שניה, הוא משום חסרון בחשיבות התוצאה להחשיב מעשה כזה כמלאכה.\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"328\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">5\u003c/sup>\u003cspan class=\"ca\" data-c=\"328\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">פטור שנים שעשאוה בשאר מלאכות – אחזו קולמוס בכותב ומח' ר\"מ וחכ' בזה יכול\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"329\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">6\u003c/sup>\u003cspan class=\"ca\" data-c=\"329\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה מצאנו דהכלילו פטור דזה יכול וזה יכול יחד עם שאר מלאכות, כגון בכותב שאחזו הקולמוס יחד, וכיון דפשוט הוא דאין גדר בכתיבה, באחיזת הקולמוס, דאינו חלק ממלאכת כתיבה, אלא חלק ממעשה כתיבה המסויים, הרי שאין זה גדר במלאכה מסויימת, אלא בגדרי מעשה, והיינו, שתוצאה זו האסורה שנעשית ע\"י שנים אין חייבים עליה, ומהא דר\"מ מחייב אפילו בזה, משמע דר\"מ סבר דאפילו בכתיבה יהיה חייב, וא\"כ מה דפוטר בזה עוקר וזה מניח אין מחמת שנעשו ע\"י שנים, אלא מחמת שלא עשה אחד מהם מלאכה שלמה, וממה דלא צריך פסוק לכתב אחד אות אחת ושני אות שניה אף לר\"מ, משמע שהוא נידון נפרד, והיינו, דבכתיבה אף שע\"י שניהם נעשה מלאכה, אין זה חשוב לצרפם, משא\"כ בהוצאה דזה עוקר וזה מניח שהיה הו\"א לחייבם.\u003c/span>"}, {"s": "h7", "h": "הוצאה כמעשה שינוי מצב של חפץ - עשיית מלאכה בשני מעשים אינה חסרון בעצם איסור המלאכה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"330\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">7\u003c/sup>\u003cspan class=\"ca\" data-c=\"330\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וביאור זה בהקדם מה שכתבנו דשאני מלאכת הוצאה משאר מלאכות, שהיא מעשה של שינוי מצב של חפץ, היינו, שחשיבות המלאכה היא בשינוי, ולא באיזה מעלה שיש באחד מהמצבים (וכמו בבורר), וא\"כ כיון שחייבה תורה על מלאכה זו, בהכרח דכל המעשה נחשב למעשה אחד.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"331\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">8\u003c/sup>\u003cspan class=\"ca\" data-c=\"331\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ותהיה משמעות הנ\"ל נוגעת בנידונים האמורים, בזה עשה הוצאה בחצי שיעור וזה בחצי שיעור פטור, אף שיחיד שעשאם אין צריך שיעשה במעשה אחד, שהרי בכתיבה אין שייכות בין כתיבה דאות אחת לכתיבה דשנים, וכן בהוצאה הוציא חצי שיעור וחזר והוציא עוד חצי שיעור חייב, שאין חצי שיעור חסרון במעשה אלא בתוצאה, שלא נחשב בזו מעשה מלאכה, כיון שאין הוא מביא לתוצאה חשובה, דחסרון זה הוא באדם שמעשה בעל תוצאה כזו אינו חשוב לו כמלאכה, וכיון שבסה\"כ עשה תוצאה חשובה, הרי שאף מעשה שעשה בחצי השיעור הוא חשוב בגלל התוצאה הסופית, ויחשבו שני מעשיו למלאכה אחת, ואם אכן הרי שאין עשיית מלאכה בשני מעשים חסרון בשם מלאכה, וא\"כ אפילו מעשה בחצי שיעור נחשב מעשה, וע\"כ אם השלים לשיעור חשוב חייב, אפילו שאין כל השיעור נעשה על ידו, וכמו בהשלים אות אחת בספר, כי גדר שיעור הוא גדר בחשיבות המעשה להיחשב כמלאכה, והרי חצי מעשה כזה חשיב כמלאכה וחייב.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1018\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">9\u003c/sup>\u003cspan class=\"ca\" data-c=\"1018\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ב. ביאור גדר פטור הנ\"ל שאינו משום חלוקת המעשה\u003c/span>"}, {"s": "h7", "h": "פטור זה עוקר וזה מניח - עקירה והנחה במשמעות הוצאה שלמה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"332\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">10\u003c/sup>\u003cspan class=\"ca\" data-c=\"332\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וא\"כ פטור דבזה עוקר וזה מניח אין הוא פטור דחצי מעשה כגדר בעצם המלאכה שלא נעשית ע\"י אחד מהם, והיינו, שאין עקירה לבד חשיבא מלאכה וכן הנחה לבד, אלא שהיה לנו לומר שכיון שנעשתה מלאכה מבין שניהם יתחייבו, והיינו, שאף שכל אחד עשה חצי מעשה, הרי יש במעשה חשיבות שהוא חלק ממלאכה.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"333\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">11\u003c/sup>\u003cspan class=\"ca\" data-c=\"333\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה בתוס' כתב דלא מסתבר שהיה לחייב את העוקר, כיון שלא נשלמה מלאכה על ידו, אבל ברש\"י משמע שגדר הפטור הוא משום שזה עשה חצי וזה עשה חצי, והיינו, שבאמת לולי המיעוט הו\"א דשניהם יתחייבו, והיינו, דכמו שאמרנו דאין זה פטור דחצי מעשה, כי יש בעוקר לבד כל גדר ההוצאה וההכנסה, וכן מצאנו דאי עקר להעביר מזווית לזווית הוא חסרון בעקירה, והיינו, שיש בעקירה עצמה גדר שהיא הוצאה, וכן במניח יש גדר שהוא מניח חפץ שנעקר מרשות אחרת, וע\"כ אין חסרון בכל חצי מעשה מה שהוא חלק ממלאכה, והיה לחייב שניהם. וע\"ז אתא הפסוק דפטור משום שצריך שיהיה מעשה שלו בכל המלאכה.\u003c/span>"}, {"s": "h7", "h": "דקדוק לישנא דרש\"י דליכא דמסייע בכולה - חסרון בגרימת המעשה ולא בשם המלאכה שנעשית"}, {"s": "p", "h": "וזה שכתב רש\"י דליכא חד דמסייע בכולה. והיינו שהיה לדקדק בלשון מסייע כאן שכתב, דיקשה הא בגמ' לקמן כתבו דאף לר\"מ מסייע פטור, דמסייע אין בו ממש, והיינו, שפטור דמסייע הוא גדר במעשה, שאין זה מעשה, אבל בזה עוקר וזה מניח כיון שבמעשה שכן עשה יש משמעות מלאכה, הרי שכבר אין חסרון במעשה להחשיב המלאכה כנעשית על ידו, אלא דאמרה תורה דצריך שכל המלאכה תהיה נעשית על ידו, ולא רק חלקה."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"334\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">12\u003c/sup>\u003cspan class=\"ca\" data-c=\"334\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וא\"כ אם היה מסייע כבר היה מתחייב שיש לו מעשה בכל המלאכה, אבל גדר פטור דהעושה כולה ולא העושה מקצתה, אין פטור משום חסרון בעשיית המלאכה אלא במעשה, דכיון דזה וזה יכולים הרי שיש חסרון בגרימה דהמעשה, והיינו, דאף שאין חסרון במלאכות שבת במה שאין נגרמות ע\"י מעשהו לבד (וכמו בזורה דרוח מסייעתו וחייב), אבל כאן הרי יש חסרון בעצם המעשה שאין הוא רק סיוע, והיינו, שגדר גרימה דמלאכות שבת אין הוא גדר שיהיה התוצאה שלו, שהרי אין בתוצאה חשיבות מה שהיא שלו או של אחר, אלא גדר גרימה הוא ע\"מ שיהיה שייכות בין מעשה שלו ליצירת התוצאה, וע\"כ די בסיוע שהוא שהיא גרימה שאינה מחייבת התוצאה, והיינו, שזה גדר בתוצאה.\u003c/span>"}, {"s": "h7", "h": "חילוק דיני שבת מדיני נזיקין - אי שביתה בתוצאה המגדירה מעשה וגדר חיוב אינו יכול לר\"י"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"335\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">13\u003c/sup>\u003cspan class=\"ca\" data-c=\"335\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וביתר ביאור גדר זה שהוא החילוק בין דיני נזיקין לדיני שבת, שבנזיקין החיוב הוא במה שנחסר חבירו ממון על ידו, וכיון שאין לחייב אדם על חסרון ממון חבירו לבד, שאין הוא שומר שיהיה לו חיוב להעמיד לחבירו ממון זה, הרי בהכרח שגדר החיוב הוא במה שנחשב שלקח ממון חבירו, וזה יהיה ע\"י שהממון אצלו, ואף שבהיזק אין הממון אצלו אלא הוא נאבד, צריך שיהיה המעשה כאילו לקח הממון ואיבדו, וגדר מעשה זה הוא פעולה בממון, היינו, שיהיה המצב האבוד נעשה על ידו, וההבדל בין מעשה דחוסר שמירה ומעשה דלקיחה הוא במה שהוא יהיה הגורם היחיד למצב הנ\"ל, וע\"כ במקרה שהמצב נעשה גם ע\"י דבר אחר יש לפוטרו, אבל בדיני שבת אין גדר התוצאה אלא בחשיבות המעשה, היינו, להחשיב מעשה שלו כמלאכה. וע\"כ אף שתהיה התוצאה ע\"י דבר אחר, אם לא יהיה גרימת הדבר האחר נחשב בלהגדיר את המעשה הכולל כמלאכה שלו אין לפוטרו.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"336\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">14\u003c/sup>\u003cspan class=\"ca\" data-c=\"336\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וכיון שכן אין חסרון בעצם זה שמעשה המלאכה נעשה גם ע\"י דבר אחר, וע\"כ אם יש לומר שהמעשה שלו הוא מעשה מלאכה, יש לחייבו אפילו אם הוא רק מסייע, אלא שבאינו יכול אין נחשב מעשה שלו כמלאכה. אלא שא\"כ יש להקשות כיון שבאינו יכול אין נחשב מעשה שלו מלאכה, למה יתחייב לר\"י, וע\"ז אמר רש\"י שכיון ששניהם אין יכולים הרי שכך הוא דרך עשיית מעשה זה, וגם המסייע יתחייב כאמור, אבל בזה שהשני יכול הרי שאין במעשהו שם מלאכה.\u003c/span>"}, {"s": "h7", "h": "בירור בשקו\"ט דגמרא בפטור שנים - חילוק גרימת המעשה בפועל מחשיבות המעשה ביצירת המלאכה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"337\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">15\u003c/sup>\u003cspan class=\"ca\" data-c=\"337\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וזה ברור, דהא פשיטא דבכל המקרים הנ\"ל איירי שמעשה המסויים שעושים, שניהם גורמים, והיינו, שודאי שאם אחד מהם יחדל מלעשות יצטרך השני להגביר את פעולתו, וא\"כ אין הבדל בעצם גרימת המעשה, וודאי שאף בזה יכול וזה אינו אין היכול עושה מעשה לבדו, והמעשה בצורתו נגרם גם ע\"י השני.\u003c/span>"}, {"s": "p", "h": "ומה דתלו הכא גדר המעשה המסויים במעשה אפשרי, הוא משום דאין אנו באים לדון בעצם גרימת המעשה, אלא במה שנחשב הגרימה כמעשה ביחס לעשיית מלאכה, וע\"כ לא יהיה חשיבות עשיית המעשה בפועל, אלא בגדר מה שהמעשה חשוב ביצירת המלאכה, וזה גדר בכל אחד לבדו האם נחשב מעשהו מעשה מלאכה."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"338\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">16\u003c/sup>\u003cspan class=\"ca\" data-c=\"338\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וע\"כ אם יחשב שכל אחד עשה חצי מלאכה ודאי שאין לחייבו, וזה אין צריך פסוק נוסף על מה דכתיב כל העושה מלאכה, שרק מי שעשה מלאכה חייב, ואין חצי מלאכה נחשבת למלאכה, ואין זה נחשב אפילו חצי שיעור.\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"339\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">17\u003c/sup>\u003cspan class=\"ca\" data-c=\"339\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">העברה שתי אמות ושתי אמות - פטור עוקר ומניח אינו במלאכה עצמה אלא בגדרי מעשה\u003c/span>"}, {"s": "p", "h": "וכן דהא לגבי העברה ד\"א ברה\"ר, פשיטא דאם יעביר זה ב' אמות וזה ב' אמות אין זה כלום, ומה שאנו דנים הכא הוא משום שזה העוקר וזה המניח אין זה גדר במלאכה עצמה, שהרי הונחה מאליה גם פטור אף שאין שם אחר, אלא זה גדר רק במעשה, היינו, שלא נחשב המוציא בלי להניח או לעקור כעושה מעשה הוצאה, ולכאורה זה גם מוכרח מעצם מה דעוקר ומניח הם כשני מעשים, והיינו, שאין זה מעשה ארוך, אלא זה גדר במה שתחשב ההוצאה נעשית, ולא מאליה, היינו, שלולי ההנחה אין נחשבת יציאת החפץ אחת, אלא כאילו היה חפץ זה כאן ועתה הוא כאן, ואין מלאכת הוצאה אלא בחפץ שהיה בפנים, היינו, שיש משמעות במה שהוא בחוץ זה שלפני כן היה בפנים, וע\"ז היה אפשר לומר, שהרי ע\"י השני נחשב שחפץ זה שלפני כן היה בפנים יצא, וכן להיפך, וכמו שכתבנו זה שייך רק במלאכת הוצאה שהיא גדר מעשה דשינוי מצב, וכיון שכך יש להחשיב אף מעשה שגורם חצי מהמלאכה כמעשה מלאכה (וכמו בזורה ורוח מסייעתו)."}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1019\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">18\u003c/sup>\u003cspan class=\"ca\" data-c=\"1019\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ג. ביאור גדר פטור הנ\"ל כחסרון במעשה\u003c/span>"}, {"s": "h7", "h": "מיעוט פרשת חטאת בעוקר ומניח - אין היחיד מתחייב בחטאת ע\"י מעשה שנעשה ע\"י חבירו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"340\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">19\u003c/sup>\u003cspan class=\"ca\" data-c=\"340\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וממילא בזה עוקר וזה מניח אי לאו דאיתא לקרא היה לחייב שניהם, והיינו, דכל חד הוה כרוח מסייעתו לגבי אידך, וגדר הלימוד דיחיד ולא שניים, היינו, ממה שאמרה תורה שגדר חטא שלו, הוא בעשייה שלו, אין זה גדר בפטור משום שנים שעשאוה, היינו, שיש חסרון בעצם זה שיש אחר שעושה עימו, דזה אינו פטור בחד, וגם אין שייך שיהיה בזה הבדל בין יכול ולא יכול, אלא הרי זה כמראה מקום בגדר החיוב שצריך שיעשה ע\"י אחד.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"341\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">20\u003c/sup>\u003cspan class=\"ca\" data-c=\"341\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ופטור דזה עוקר וזה מניח הוא בגדר המעשה בו אף עשיית המלאכה היא חלק מהחטא, וזה הרי גדר בכל עבירות שחייב עליהם חטאת, ואין לזה שייכות עם מעשה מלאכה, והיינו, שאין היחיד מתחייב ע\"י מעשה חבירו, וכיון שבלי הנחת או עקירת חבירו לא היה מתחייב אין עשייתו מחייבתו, שאין זה מעשה המחייב חטאת.\u003c/span>"}, {"s": "h7", "h": "לימוד מיעוטי הנ\"ל הוו היחס לחטאת היחיד - יחיד שעשה בהוראת ב\"ד ופטור זה עוקר וזה מניח"}, {"s": "p", "h": "וראה דלימוד זה אינו אלא ביחס לעשיית היחיד, שעשייתו מחייבתו, והיינו, שלימדה תורה שאין חייב חטאת אלא בעשייה שיש בה חטא היחיד, וזה גדר מה שיש ללמוד מפסוק זה גם יחיד שעשה בהוראת ב\"ד, היינו, שזה גדר בחטאת הבאה ע\"י יחיד, שלא באה אלא משום חטא שעשה בעשייה שלו, ויש בזה גם (כדי לימוד) מיעוט יחיד שעשה בהוראת ב\"ד, דגדר פטורו משום מה שאין החטא עשייה שלו לבד, שהרי החטא הוא בשגגת הלב ובעשייה, וכשנאמר שע\"י עשייה חטא בשגגה, היינו, שעשייה שלו היא בעקבות מה ששגג, וכיון שכך הורו ב\"ד הרי שאין זה עשייה שלו לבד, אלא חלק מכלל עשיות דהוראת ב\"ד. וכן לגבי פטור דזה עוקר וזה מניח דכיון שמעשה זה אינו אלא ע\"י אחר אין חשיב עשיה שלו, והיינו, שהיה לכתוב ואם נפש תחטא בשגגה בעשות וכו'."}, {"s": "h7", "h": "חילוק זעוז\"מ משנים שהוציאו יחד - ביאור דברי רש\"י שאין דרך לעשותו בשנים ביחס למלאכה"}, {"s": "p", "h": "אבל בשנים שהוציאו יחד, היינו, שעקרו והניחו, ויש לכל אחד עשיית מעשה בכל המלאכה, כיון שכמו שאמרנו אין פטור דשנים שעשואה משום שנעשה בשנים, אלא משום חסרון שיש בכל אחד במעשה שנעשה ע\"י שנים, אלא דילפינן לה ממה דכתב בלשון יחיד, ויש בזה הגדרה של מעשה של אחד לעומת שנים, דהא במעשה המסוים הרי תמיד כל חד חשיב אינו יכול, כדאמרינן בתוס' דאיירי שאוחזין את הדבר בצורה שהוא נסמך על שניהם, וא\"כ לא יהיה נפק\"מ למעשה זה במה שיכול לבד, אלא הוא גדר במעשה דחד. וכתב ברש\"י שגדר החסרון דזה וזה יכולים משום שאין דרך לעשותו בשנים, ולכאורה לפי מה שאמרנו, היינו, פירושו שכיון שהאחד יכול לעשותו לבדו, הרי שיש במה שהשני מסייע גירוע בחלק עשייתו, והיינו, שכיון שדרך לעשות זה בחד, הרי שגדר מעשה דהאי מלאכה לגבי חד הוא בעשיית כולו, וכיון שחלקו נעשה ע\"י אחר הרי שלא עשה מעשה הגורם למלאכה."}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1020\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">21\u003c/sup>\u003cspan class=\"ca\" data-c=\"1020\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ד. ביאור דברי רש\"י בזיוז\"י דאין דרך בשנים\u003c/span>"}, {"s": "h7", "h": "בירור בדברי רש\"י דאין דרך לעשותו בשנים - אמאי מחייבינן בזה יכול וזה אינו יכול"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"342\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">22\u003c/sup>\u003cspan class=\"ca\" data-c=\"342\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">אך זה קשה שהרי בזה יכול וזה אינו יכול, חייב זה שיכול לכולי עלמא, והרי גם הכא לגביו אין דרך לעשות מלאכה זו בשנים, ומאי נפק\"מ, דאידך הוי רק מסייע, דזה רק סיבה לפוטרו, ולא לחיוב זה שיכול. ובאמת דעיקר דברי רש\"י צ\"ב, דכיון דאיתא לזה יכול וזה אינו יכול בהכרח דגדר יכול הוא ביחס לשני אלה, ולא ביחס לכל העולם, וא\"כ אין זה שייך לדרך עשיית המעשה שודאי אינו נקבע ע\"י שני אלה ויכולותם.\u003c/span>"}, {"s": "p", "h": "וע\"כ נראה דודאי אין כוונת רש\"י במה שאמר אין דרך, כמו שאר אין דרך דמסכתין, אלא כוונתו ביחס לשני אלה, וא\"כ יקשה ביותר אמאי מחייבינן בזה יכול וזה אינו את מי שיכול, ואיפכא מסתברא דבהאי דיכול איכא חסרון דאין דרכו בכך ויש לפוטרו, ובהאי דאין יכול הרי דרכו בכך ויש לחייבו."}, {"s": "h7", "h": "גדר מעשה באחד לעומת שנים - מעשה מלאכה אין בו מעלה לגורם יחיד"}, {"s": "p", "h": "וע\"כ נראה דהכי פירושו, דהנה הרי הפסוק איירי בחיוב חטאת דחד, וקרא יתירה דכתיב הכא מתייחס לגדר מעשה האחד לעומת מעשה דשנים, וכיון דכמו שאמרנו אין חסרון לגבי מלאכה במה שאין העושה הגורם היחיד, או המספיק לתוצאה, דעיקר גדר מלאכה הוא מלאכת מחשבת, היינו, שיש בתוצאה היוצאת יותר ממה שגרם המעשה (וכמו מה ששיעור מלאכה הוא גרוגרת ופחות מכאן פטור, אף שלא יהיה שינוי מעשה לצורך תוספת השיעור הנ\"ל, וכו'), ואין המעשה אלא חלק ממחשבת תוצאה, ובהכרח דאין מעלה באחד על שנים מה שבאחד הוא הגורם היחיד ובשנים אינו."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"343\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">23\u003c/sup>\u003cspan class=\"ca\" data-c=\"343\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וא\"כ הדרן לדוכתן שהגדר הוא בשניהם יחד, וזה קשה כנ\"ל דהרי אין זה דין בשנים אלא באחד, ולמאן דמחייב, שניהם חייבים חטאת נפרדת.\u003c/span>"}, {"s": "h7", "h": "גדר איסור לא תעשה כל מלאכה - התוצאה מגדירה מעשיהם כאי שביתה וגדר המיעוט דשנים שעשאוה"}, {"s": "p", "h": "ונראה לומר שאיסור עשיית מלאכה בשבת, היינו, מאי דכתיב לא תעשה כל מלאכה יש בו מיעוט בגדר מעשה, דאין הוא אלא מה שעושה מלאכה, והיינו, שאין במעשה גדר אלא במה שעל ידו נחשב העושה עושה את המלאכה, והיינו, שבאמת מה שנאסר הוא התוצאה, ומה שלא נאסרה רק על האדם (היינו עבודה), הוא משום שאין משמעות מלאכה סתם יצירה שיש לה משמעות אצל האדם, אלא הוא גדר בעשיית האדם מה שהיא חסרון שביתה, והיינו, שדברים המותרים הם מה שאין בעשייתם אי שביתה, וא\"כ אף לגבי פטור דשניים שעשאוה יהיה גדר המעשה הפטור מה שבשנים אין זה אי שביתה, וכיון דאיתעבדא מלאכה מבינייהו הרי שהיה לחייבם, שתוצאה זו שחשובה מלאכה מגדירה את מעשיהם כאי שביתה, ואם מצאנו גדר פטור דמעשה בקרא, הרי שיהיה זה לפי מה שהוא פחות אי שביתה בשנים מבאחד, והוא שע\"י שגם השני עושה המעשה נחשב אחד פחות לא שובת, והיינו, דכיון דאיתעבדא מלאכה מבינייהו ממילא מוכרח שהיה במעשיהם חוסר שביתה, וכיון שאין חוסר השביתה גדר בכמות המעשה, הרי שיש לחייב שניהם, דלא שבתו."}, {"s": "h7", "h": "חסרון מעשה שאינו ראוי לשנים - חילוק עושה מקצתה מזה עוקר וזה מניח שאינו אלא חציה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"344\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">24\u003c/sup>\u003cspan class=\"ca\" data-c=\"344\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובזה אין למצוא חסרון במעשה דשנים מבאחד לגבי חד אלא במה שאין המלאכה שנעשית ראויה לשנים, היינו, שאין היא חשובה דיה שיעשוה שני אנשים, וע\"כ כל אחד מהשנים לא נחשב שלא שבת ע\"י עשיית מלאכה זו, והנה גדר זה קראוהו בגמ' עושה מקצתה ולא עושה את כולה, ואין זה אותו הגדר כמו זה עוקר וזה מניח, שזה אינו גדר דמקצתה אלא חציה, והיינו, דבזה עוקר וזה מניח הרי המלאכה עצמה חלוקה, שהרי מלאכת הוצאה עשויה משני מעשים, והוא עשה רק אחד מהם, וזה חציה. אך שנים שהיו אוחזים וכו' הרי יש לכל אחד חלק בכל המלאכה, ואין למצוא חילוקה אלא משום שנעשית ע\"י שנים, היינו, דתוצאת המלאכה מגדירה את המעשה המשותף הנ\"ל כמלאכה, אלא כיון שאין לחייב אחד אלא על מה שעשה, הרי שעשה רק קצת מהמלאכה.\u003c/span>"}, {"s": "h7", "h": "גדר זה יכול וזה יכול – חילוק גדר מעשה הנעשה בשנים ממשמעות אי שביתה דכל אחד"}, {"s": "p", "h": "ועתה נשוב לגדר זה יכול וזה יכול במה שכתב רש\"י שיש בזה חסרון מה שאין דרכם לעשות זאת בשנים, וכמו שכתבנו זה תלוי בשני אלה דווקא, דגדר הפטור הוא מה שאין נחשב שלא שבתו בעשייה זו, ע\"י שאין מלאכה זו חשובה שתהיה ראויה להיעשות ע\"י שני אלו, והיינו, שנמצא כאן שני גדרים דמה שבפועל שניהם נושאים את הדבר יחד, היינו, שאם יעזוב עתה אחד מהם יהיה הדבר נופל מיד השני, הוא מה שמגדיר את המלאכה כנעשית ע\"י שנים, אך גדר אי שביתה שיש שבעשייתם ע\"י שנעשית המלאכה הוא גדר שני ואינו תלוי במעשה בפועל, כיון שהוא גדר בחיוב כל אחד בנפרד, והיינו, שאין במה שבפועל נושאים יחד ואין אחד נושא לבד סיבה לומר שאין מעשה האחד אי שביתה, דכיון דאיתעבדא מלאכה מבינייהו הרי שהיה במעשהו אי שביתה."}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1021\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">25\u003c/sup>\u003cspan class=\"ca\" data-c=\"1021\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ה. ביאור המח' בחילוק רוח מסעייתו משנים שעשאוה\u003c/span>"}, {"s": "h7", "h": "חילוק בעשה ורוח מסייעתו משנים שעשאוה – בזור\"מ די בכוונתו אך באדם אחר צריך גם כוונתו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"345\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">26\u003c/sup>\u003cspan class=\"ca\" data-c=\"345\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובביאור זה יש להקדים מה שיש לחלק בין עשיית מלאכה ע\"י כוח אחר, לבין ע\"י אדם אחר, דהא זורה ורוח מסייעתו ודאי שאף מה שעשתה הרוח נחשב מעשה שלו דליכא לזורה בלא זה, וגדרו הוא דכיון שמלאכת מחשבת אסרה תורה הרי שאף כוח שלו אינו נחשב מעשה מלאכה, אלא משום שיש בו כוונת עשיה למלאכה, וע\"כ אף מעשה הרוח אף שהיא כוח אחר כיון שיש בה כוונה שלו למלאכה חייב, והיינו, שיש במעשה שני חלקים, האחד, הוא כוחו, והשני, הוא הכוונה.\u003c/span>"}, {"s": "p", "h": "ואמנם שונה כוחו מכוח הרוח, שאינה ממנו, אך הרי אין מעשה הרוח בזרייתה אלא ע\"י שכיוון התבואה באופן שהרוח תועיל לזריה ע\"י הגבהת התבואה ופיזורה, וע\"כ נחשב שאף מעשה הרוח שלו, שזה גדר מעשה מלאכה. אך באדם אחר הרי אין די בכוונתו, וצריך שגם האדם האחר יכוון את מעשהו למלאכה, וא\"כ יש כאן שתי כוונות בכל אחד, כוונת המעשה למלאכה, וכוונת מעשה שלו שיפעל עם השני למלאכה. וא\"כ החסרון בשנים שעשאוה הוא מה שאין די בכוונת האחד ליצירת המלאכה (ובפרט לירושלמי דאף בהוצאה איכא לחיובי ברוח מסייעתו)."}, {"s": "h7", "h": "דעת ר\"מ בחילוק הנ\"ל משנים ומזעוז\"מ – דכיון כוחו הוי בכל המעשה ודי בכוונתו כמו בזור\"מ"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"346\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">27\u003c/sup>\u003cspan class=\"ca\" data-c=\"346\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ודעת ר\"מ שאמנם אין זה כזורה ורוח מסייעתו, כיון שצריך לכוונת האחר, אך זה חיסרון רק במקרה כמו זורה שאין לו שייכות עם המעשה הדורש כוונה, היינו, שאין לו שייכות בכוח שעושה הרוח אלא רק בכיוונה, וכן בזה עוקר וזה מניח שאין לו שייכות עם כוח המעשה דהנחה, ואין די בכוונת עקירתו להנחה, וזה עשה מלאכה שלמה, אך בשנים שהיו אוחזים כיון שיש לו כוח בכל המעשה, וממילא גם במעשה חבירו, די בכוונתו ואין זה שניים אלא כל אחד לחוד.\u003c/span>"}, {"s": "h7", "h": "דעת ר\"י בחילוק זה וזה יכול מאינו יכול - תלותם יוצרת מעשה אחד משא\"כ ביכולים שעושים בנפרד"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"347\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">28\u003c/sup>\u003cspan class=\"ca\" data-c=\"347\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ודעת ר\"י דאין די בזה, וכיון שלא יעשה המעשה בלי כוונת השני הרי שנחשב שעשאוה שנים, אלא דדעתו שאין חסרון בעשאוה שנים, אם יהיה זה מעשה אחד של שניהם, והיינו, דכיון ששניהם מתכוונים למעשה אחד, הרי שיש לכל אחד שייכות עם כוונת השני, דכיון שאף לשני לא די בכוונת מעשהו לבד, אלא הוא צריך לכוונת הראשון, הרי שיש לראשון שייכות גם עם כוונת השני, וכל אחד חייב לעצמו. אך אם אינם צריכים זה לזה ויכול כל אחד לעשות המעשה לבד, הרי שאין זה מעשה אחד, דאין לראשון שייכות עם כוונת השני, וא\"כ הרי כל אחד עושה את מעשהו בנפרד, וביחס למלאכה זו נחשב שעשה רק מקצתה וזה נתמעט לפטור.\u003c/span>"}, {"s": "h7", "h": "דעת ר\"ש בפטור שנים שעשאוה - צורך בכוונת השני פוטר וחילוקו מאחד יכול ושני אינו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"348\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">29\u003c/sup>\u003cspan class=\"ca\" data-c=\"348\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ודעת ר\"ש דשנים שעשאוה פטורים, והיינו, דכל שצריך לכוונת השני הרי נחשב שאין זה מעשה שלו לבד, וכמו שכתבנו דאין זה כזורה ורוח מסייעתו, דכיון דצריכים לכוונת כוח השני הרי שאין די בכוונת האחד, ואין מלאכה זו נעשית ע\"י כוונת אחד אלא ע\"י כוונת שנים, ואין מתחייב אלא יחיד ולא שנים. אך אם יהיה אחד יכול והשני לא יכול שאין הראשון צריך לכוונת השני, הרי שנחשב מעשה שלו לבד, ואין זה מעשה של שנים.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1022\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">30\u003c/sup>\u003cspan class=\"ca\" data-c=\"1022\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ו. בגדר מסייע האמור כאן ובטומאה\u003c/span>"}, {"s": "h7", "h": "שייכות גדר מסייע דטומאה לשבת - טומאת מדרס מגדירה מעמידיה כדריסה ומלאכה מגדירה המעשה כאי-שביתה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"349\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">31\u003c/sup>\u003cspan class=\"ca\" data-c=\"349\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">והנה ביאור שייכות גדר מסייע דטומאה כאן, הוא בהקדם מה שכתבנו, שודאי לכל דיני התורה השייכים במעשה אין גדר במה שזה יכול לבד אם לא היה זה, דכיון שעשוהו יחד הרי זה מעשה של שניהם בשווה, אלא דכאן כיון שאין גדר המעשה האסור, אלא במה שהוא אי שביתה, וזה ע\"י מה שהוא עושה מלאכה, והיינו, שאין האיסור אלא באי שביתה, ואי שביתה נחשב ע\"י שעושה מלאכה, וכמו בזורה ורוח מסייעתו שנחשב שזרייתו והרוח יחד עושים מלאכה, וע\"כ מעשה זרייתו לבד נחשב לאי שביתה.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"350\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">32\u003c/sup>\u003cspan class=\"ca\" data-c=\"350\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וזה אמרו בגמרא דכן מצאנו בענין מדרס, היינו, דאין זה גדר מעמיד דזב או שנרדס ע\"י הזב, אלא מה שהזב דורס עליו, ומה שמעמיד דריסה זו נחשב כמדרס הזב, והצד השווה שבהם שאין גדר המעשה כגורם הוא שם המעשה, אלא המעשה עצמו מוגדר ע\"י התוצאה, והדימוי דכמו שחשיבות המלאכה מגדירה את המעשה כאי שביתה, כך טומאת הזב מגדירה את מעמידיה כמדרס.\u003c/span>"}, {"s": "h7", "h": "ראיית הגמ' מדין שיעור זיבה וטביחה - שיעור חשיבות תוצאה המגדיר המעשה כטביחה וכאי שביתה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"351\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">33\u003c/sup>\u003cspan class=\"ca\" data-c=\"351\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובזה יבואר הוכחת הגמ' דאין צריך שיעור לזה ושיעור לזה, מהא דאין צריך שיעור זיבה לזה ושיעור זיבה לזה, דכמו דשיעור גרוגרת הוא חשיבות המלאכה, כך שיעור זיבה הוא חשיבות הטומאה, וכן הוא לגבי טביחה, וכמו כשכתבו בתוס' דליכא בכפל, דגדר כפל אין בו משמעות מלבד גדרו הממוני של הקרן, אך טביחה אין הוא גדר ממוני ואין בטביחה יותר מסתם איבוד ביחס לממון שבו, וא\"כ אין גדר מה שטבחו גדר ממוני, אלא דדין ארבעה וחמישה מגדיר את מעשיהם כטביחה וכו'.\u003c/span>"}, {"s": "h7", "h": "מה שלא נסתפקו בגמ' אלא בז\"יוז\"י לר\"מ - חילוק בין מעשה שיש בו כדי חיוב נפרד באחד מבשנים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"352\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">34\u003c/sup>\u003cspan class=\"ca\" data-c=\"352\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה מה שלא נסתפקה הגמ' אלא בזה יכול וזה יכול לדעת ר\"מ, ולא בזא\"י וזא\"י לר\"י הוא כמ\"ש דלדעת ר\"מ אין גדר המעשה המחייב כל אחד שייך אחד לשני, וכל אחד חייב על מעשהו בנפרד, שאין הוא צריך לחלק המעשה של חבירו. וע\"כ היה להסתפק שנצטרך חשיבות מלאכה לכל אחד בנפרד, אבל לר\"י בזא\"י וזא\"י הרי גדר המעשה הוא בשניהם יחד, אלא דדעת ר\"י דעכ\"פ כל אחד חייב על מעשה כזה, וא\"כ ודאי שאין צריך שיעור לכל אחד.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1023\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">35\u003c/sup>\u003cspan class=\"ca\" data-c=\"1023\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ז. ביאור גדר פטור דזה עוקר וזה מניח\u003c/span>"}, {"s": "h7", "h": "חסרון זה עוקר וזה מניח - חסרון עשה מקצתה וחסרון דעביד פלגא לר\"י ולר\"מ"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"353\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">36\u003c/sup>\u003cspan class=\"ca\" data-c=\"353\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה אחר כל זה נראה לבאר גדר פטור דזה עוקר וזה מניח, דאית ביה תרתי לריעותא, האחד, מה דעביד האי לא עביד האי, דאף אי נימא דאין פטור דשנים שעשאוה וכר\"י, ויש להחשיב זה כמעשה אחד של שנים, הרי יש לפטור משום שעשה כל אחד רק מקצתה ולא עשה כולה. ואף לר\"מ דליכא לפטורא דעשה מקצתה אין זה אלא במקום דסייע בכולה, אבל הכא זה עביד פלגא וזה עביד פלגא, אבל לר\"ש אין צריך לכל זה, דכיון שליתא למלאכה אלא ע\"י שניהם פטור מ\"מ.\u003c/span>"}, {"s": "h7", "h": "דקדוק לשון הברייתא בריש מסכתין - גורם התוצאה ומבטל השביתה כשני גדרים במלאכת מחשבת"}, {"s": "p", "h": "ונראה דזה דקדוק דברי הגמרא בריש מסכתין בבריתא דרבי דהביאו לגבי פטור דזה עוקר וזה מניח גם דין דהעושה מקצתה וגם דין דשנים ועשו אותה וגם לדין דשנים ועשאוה."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"354\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">37\u003c/sup>\u003cspan class=\"ca\" data-c=\"354\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה בגמרא משמע דאין חיוב יכולים דר\"י קשור לפטור דהעושה מקצתה, דהגמ' הביאה דין שנים שהיו וכו' ואחר כן ר\"י אומר את כל הדין מחדש ומחלק בין לא יכולים ליכולים, ומשמע דלא יכול הוא סיבה לחיוב, ואי ליכא פטורין, ואהא קאי ר\"ש דאע\"פ שלא יכול פטור, ומשמע שחולק אלימוד דהעושה ומקצתה, ואומר דלכך נאמר בעשותה שנים וכו'. ובבריתא יש שינוי לשון בדר\"מ מחייב ור\"י אומר חייבין ופטורים.\u003c/span>"}, {"s": "p", "h": "ונראה ע\"פ מש\"כ דאין גדר הפטור בכל הני לר\"ש כגדר ר\"י, וכן לר\"מ, דלר\"מ ליכא לפטורא דעשה מקצתה, ויותר מזה מצאנו דגדר חיוב זה יכול וזה יכול לר\"מ הוא משום כל חד בנפרד דיש בתוצאת המלאכה להחשיב מעשה שלו כמעשה מלאכה, והוכיחו דלא צריכא לשיעור לזה ולזה ממטה דזב, ומשמע דאין בגדר חיוב זה שייכות לדין חטאת."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"355\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">38\u003c/sup>\u003cspan class=\"ca\" data-c=\"355\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והיינו, שהרי קרא דחטאת לא איירי דווקא באיסור שבת, ובהכרח דאין גדר הפטור במלאכה אלא במעשה ככלל, והיינו, דאף דמעשה מלאכה יש בו גדרים נפרדים, כמלאכת מחשבת וכו', אך יש שיתוף בגדרי המעשה הנוגעים לחיוב חטאת בין כל חייבי חטאות, וכמו שכתבנו גדר מעשה מלאכה הוא גדר במה שהוא מבטל שביתה, היינו, שתוצאה שנעשית יש בה להגדיר את העושה אותה כמבטל שביתה, וכיון שאין במעשה עצמו גדר איסור אלא בתוצאתו, ואין בתוצאה אלא מה שהיא גדר במעשה, הרי שיש כאן שני גדרי מעשה, דאין המעשה כמחשיב את העושה כגורם התוצאה באותו הגדר עם המעשה האסור, דגדר המעשה המחשיב את העושה כגורם התוצאה, אין בו משמעות איסור, והמעשה האסור אין בו משמעות כגורם התוצאה, וזה גדר מלאכת מחשבת [ודמי לדין שיעור מלאכה דילפינן שיעור גרוגרת מדין מלאכת מחשבת, והיינו, דאין שיעורו כשיעור דאכילת איסור, דשיעור דאכילת איסור הוא גדר במעשה האסור, היינו, שיחשב כאכילה שהיא המעשה האסור, אבל בשיעור דגרוגרת אין לזה שייכות עם גדר המעשה כאסור אלא זה שיעור בתוצאה, וזה ברור, שהרי לית לן למימר דגרוגרת היא שיעור מעשה דקוצר ובורר וכו', אלא הוא גדר בתוצאה חשובה, ואין גדר דתוצאה חשובה לגבי המעשה, אלא ביחס למה שיחשב עשיה של מלאכה, וע\"כ לא יהיה שיעור בדבר הראוי לשימוש אלא בדבר הראוי להכנה.].\u003c/span>"}, {"s": "h7", "h": "גדר מעשה שבת לגבי חיוב חטאת - מיעוט שנים אינו בגרימת התוצאה אלא בחצי מעשה האסור"}, {"s": "p", "h": "וא\"כ הרי שגדר מעשה דשבת במה שיש להשוותו לשאר איסורים ולגבי חטאת, אין זה מעשה הגורם, אלא מעשה האיסור דאי שביתה. ובזה נמצא גדר אחר בשנים שעשו משאר איסורים בשני מובנים, האחד, במה שתוצאת המעשה עומדת לעצמה. והשני, שהאיסור הוא המעשה עצמו ולא גרימת התוצאה."}, {"s": "p", "h": "וע\"כ יהיה מיעוט דשנים לגבי חטאת לא ביחס למעשה כגרימת התוצאה, היינו, מה שאין הוא הגורם לתוצאה לבד, אלא למעשה עצמו דהוא האיסור, וע\"כ לא יהיה חסרון במה שיהיו שנים חייבים על תוצאה אחת, ושנאמר שלא עשה כל אחד אלא חצי תוצאה, אלא במה שיחשב המעשה שעשה חצי מעשה."}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1024\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">39\u003c/sup>\u003cspan class=\"ca\" data-c=\"1024\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ח. גדר איסור במעשה דחד משנים שעשאוה\u003c/span>"}, {"s": "h7", "h": "חילוק גדר מעשה דחד משנים שאינו גרימה - תוצאת המלאכה מחשיבה מעשה כל אחד כמעשה איסור"}, {"s": "p", "h": "וביתר ביאור דכיון שאין גדר במעשה האסור גדר גרימה, הרי שאין הגדרתו כאסור נבחנת לפי חלקו במה שגרם, אלא במה שעשה, וכיון שכן הרי שנמצא שני גדרים אפשריים במעשה דחד שהוא חלק משתים, או בחצי מעשה אסור, או בחלק מועט במעשה האסור."}, {"s": "p", "h": "ושתי גדרים אלו לא שייכים במעשים שאינם בגדר זה, היינו, דכמו שנתבאר גדר הנחשב מעשה אסור הוא בחשיבות התוצאה להגדיר המעשה, דבמעשים שגדרם גרימת תוצאה אסורה, אם יהיה מעשה שנים בזה אחר זה, הרי אין במעשה הראשון גדר גרימה כלל, שכיון שכשנגמרה גרימתו לא נעשתה התוצאה, אין לה שם גרימה כלל, ואם יעשו שניהם מעשה יחד הגורם לתוצאה אחת, יהיה זה תלוי באם אפשר לחלק התוצאה לשנים שיחשב שכל אחד עשה אחד."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"356\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">40\u003c/sup>\u003cspan class=\"ca\" data-c=\"356\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">אך במעשה שאין גדר תוצאה שלו אלא בהחשבתו כמעשה אסור, הרי שיש גדר בכל המעשה כמעשה איסור אחד, מחמת התוצאה שהחשיבה המעשה כאסור, וא\"כ יהיה גדר מעשה דכל חד מעשה אסור. וע\"כ יש בחשיבות התוצאה דמלאכת הוצאה להחשיב זה עוקר וזה מניח כמעשה אחד אסור, וממילא להחשיב כל אחד כעשה מעשה איסור, וכן בשנים שהוציאו דנחשב מעשה שניהם יחד כמעשה אסור, וממילא כל אחד חשוב שעשה מעשה האסור.\u003c/span>"}, {"s": "h7", "h": "גדר פטור מקרא דחטאת בכוחו דחד במעשה - מיעוט פעולת אחד ולא שנים כסיבת המעשה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"357\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">41\u003c/sup>\u003cspan class=\"ca\" data-c=\"357\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">אך הנה גדר דפטור מקרא דחטאת הרי אינו נוגע לגדרו המיוחד של מעשה מלאכה, וע\"כ גם מיעוט שנתמעט אינו נוגע לגדר זה, והיינו, דאמנם אין המיעוט לגבי מלאכת שבת אלא בגדר מעשה שלה, אבל מיעוט דאחד ולא שנים הוא גדר בכוח המעשה, וכאמור שאמנם אין גדר האיסור בשבת גדר גרימה, אך החלוקה בין אחד לשנים אכן נוגע לכוחם במעשה, והיינו, דכמו דבאיסורים שגדר מעשה שלהם הוא גרימה, היינו, מה שהתוצאה נעשית מכוחו, גדר העושה בגרימה הוא מה שכוח פעולתו הוא סיבה מספקת לגרימת התוצאה, כך לגבי שבת גדר העושה במעשה הוא מה שכוח פעולתו הוא סיבה למעשה.\u003c/span>"}, {"s": "h7", "h": "חילוק גדר מעשה דעושה כגרימה מגדרו ככח דמעשה - שייכות דין שנים שעשאוה אף בזורה ורוח מסייעתו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"358\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">42\u003c/sup>\u003cspan class=\"ca\" data-c=\"358\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה הבדלנו בין גדר מעשה כגרימה, ששם אין משמעות בכוח אלא כסיבה מספקת, אך כמו שכתבנו כיון שבשבת אין גדר המעשה גרימת התוצאה, אין צורך שיהיה כוחו סיבה מספקת, דזה חסרון רק במעשה גרימה דתוצאה, אך בכוח דמעשה עצמו, משמעות כוח דחד הוא במה שנחשב המעשה לשלו, ולדוגמא דדין שנים שעשו יהיה שייך אף בזורה ורוח מסייעתו, והיינו, דאף שאין המעשה דשניהם יחד מסייע בכל מעשה הגרימה, עדיין יש לדון על כל אחד בגדר כוחו בזרייה לבדה.\u003c/span>"}, {"s": "h7", "h": "יסוד החסרון בזה עוקר ומניח - הוצאה מורכבת משני מעשים והמיעוט ממעט חצי כח המעשה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"359\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">43\u003c/sup>\u003cspan class=\"ca\" data-c=\"359\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ועתה יבואר מה שיש בזה עוקר וזה מניח יותר סיבה להיכלל במיעוט דקרא הנוגע לכח העושה במעשה, והיינו, דכמשנ\"ת אין מלאכת הוצאה כשאר מלאכות, שמעשה דהוצאה כיון שגדרו שינוי ממצב אחד למצב שני, הרי ששייך לחלק את המעשה לשתי כוחות, וכמו שכתב תוס' דאין שייך זה בכתיבה, שאין שתי אותיות גדר חצי מעשה, אלא זה שני מעשים חלוקים, ואף שבחד יש בהם יחד להחשיב את המעשה הכולל כמלאכה, אין גדר חלוק במעשה עצמו, שאפשר שיעשה זה במעשה אחד שיכתוב שניהם בכוח אחד. אך בהוצאה כיון שהיא עשויה משני מעשים, הרי שגדר שלה כמעשה אחד הוא מעשה עם שני כוחות, וכיוון שכך אם נמצא שמיעטה תורה אחד ולא שנים יהיה המיעוט במעשה כזה שיש להגדיר את כח כל אחד כחצי כח המעשה, שיש בזה חסרון בכל אחד שאין לומר עליו שעשה את המעשה, ואף שכמו שאמרנו בזורה ורוח מסייעתו מצאנו שאין חסרון במה שאין כוחו עושה כל המעשה ומשום שאין שם מעשה על כוח הרוח ואין זה חלק ממעשה האסור, וכדלעיל.\u003c/span>"}, {"s": "h7", "h": "חיוב בזה יכול וזה אינו - מסייע אין בו ממש והא דמעשה ראשון נחשב אכל המעשה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"360\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">44\u003c/sup>\u003cspan class=\"ca\" data-c=\"360\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וזה גדר מה שחייב בזה יכול וזה אינו יכול, ואף דיש לומר דכל חד לא הוי רק מסייע, והיינו, שאין חסרון דמסייע בגדר כח, דזה כל משמעות כח שהוא מסייע, אלא חסרון דמסייע הוא במה שאינו נחשב חלק ממעשה האסור, ואין עליו שם מעשה כלל, והיינו, דכיון שגדר מעשה האסור במה שהוא אי שביתה תלוי בחשיבות התוצאה כמלאכה, ויש גדר בתוצאה להגדיר המעשה, הרי שאין מעשה שנעשה ע\"י סיוע נחשב חלק מהמעשה כשיש כח חשוב ממנו, והיינו, דכמו שאמרנו הרי אין לפטור או לחייב חד משום אידך, ובהכרח שאין גדר מסייע דאין בו ממש גורם שיהיה השני חייב, אלא הפירוש הוא דמה שהשני פטור הוא מוכיח שאין כוח שלו נחשב חלק מהמעשה, וגדר המעשה הוא רק במעשה של הראשון, וא\"כ הרי נחשב שעשה כל המעשה האסור, ואין השני אלא כרוח מסייעתו ובזה לא נחלקו.\u003c/span>"}, {"s": "h7", "h": "מחלוקת ר\"י ור\"ש בזא\"י וזא\"י - אין להעדיף כח דאיזה חד ושניהם חשיבי כעושי המלאכה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"361\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">45\u003c/sup>\u003cspan class=\"ca\" data-c=\"361\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ומעתה יבואר גדר מחלוקת דר\"י ור\"ש, והיינו, דהרי גם בשניהם יכולים, וגם בשניהם אין יכולים אין גדר מעשה שלהם אלא מסייע כמו לגבי זב, אלא שאין גדר מסייע במעשה דמלאכה פטור בעושה, אלא במה דמעשה נפעל ממנו חשיב כמעשה דמלאכה. וא\"כ כיון שאיתעבדא מלאכה מבינייהו יש להגדיר איזה מעשה כמעשה דהאי מלאכה, וכיון שאין להעדיף זה מזה, יש להחשיב שניהם בגדר מעשה המלאכה, ואין מסייע חסרון.\u003c/span>"}, {"s": "p", "h": "וזה צריך לומר אף לר\"מ דכתב רש\"י דאי הוה מסייע חד בכל המלאכה דזה עוקר וזה מניח היה חייב, ויתכן דזה אף אם יהיה סיוע זה באינו יכול לעומת יכול, כי חסרון דר\"מ אין הוא משום דהוי מסייע, אלא משום דהוי חצי מעשה דהאי לא עביד האי, אבל אי הוה חד מסייע לאידך פלגא יש להחשיב מעשהו כרוח מסייעתו, וכמו בכל זורק, ויש לחלק."}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1025\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">46\u003c/sup>\u003cspan class=\"ca\" data-c=\"1025\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ט. בגדר מעשה הנעשה בשנים\u003c/span>"}, {"s": "h7", "h": "שני חסרונות במעשה של שנים - אין כוחו פועל כולו או אין די בכוחו לפעול"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"362\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">47\u003c/sup>\u003cspan class=\"ca\" data-c=\"362\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ועכ\"פ כיון שליכא לפטורי משום מסייע, וכיון שגדר הפטור בגדרי מעשה, היינו, שאין נחשב כח שעשה להגדיר זה מעשה האסור כמעשה שלו, וכיון שגדר הפטור הוא בחד ובלי שייכות לאידך, הרי שיש למצוא במעשה של שנים שני חסרונות, או במה שאין כוחו פועל כל המעשה, וזה חסרון במה שנחשב כל המעשה שלו, או במה שאין די בכוח שפעל לעשות המעשה ,וזה חסרון בכל חלק מהמעשה שיחשב שלו.\u003c/span>"}, {"s": "p", "h": "וגדר דשניהם יכולים הוא במה שאין כוחו פועל כל המעשה, דכיון שיכול, היינו, שיש בכוחו לפעול כל המעשה, הרי שיש לו שם עושה על כל המעשה, וכיון שעשה רק מקצת מהמעשה, יש בזה חסרון במה שנחשב המעשה שלו. אבל אין זה חסרון במה שאין די בכוח שפעל בפועל, שאין זה חסרון בכוחו אלא במה שנעשה ע\"י שנים יחד."}, {"s": "p", "h": "וגדר דשניהם אין יכולים אינו חסרון במה שעשה מקצתה דזה גדר בכל המעשה, והרי אין בכוחו לעשות כולו, אלא איכא חסרון בכוחו שאין בו די לפעול כל המעשה."}, {"s": "h7", "h": "הבחנה בין שני גדרי כח - כח הפועל בכל המעשה מול כח הנבחן בכל חלק"}, {"s": "p", "h": "ולבאר יותר שני גדרים אלו, נקדים מה שיש לבאר מהו גדר כוח שפועל במעשה שיש בו להחשיב את המעשה כמעשה שלו, והיינו, דכמו שאמרנו הרי אין בגדרים אלו חסרון בהגדרת מעשה דחד כמעשה איסור, היינו, מעשה שיש בו משמעות דאי שביתה, אלא הם חסרון בגדר המעשה עצמו שיחשב שנעשה מכח זה, והיינו, שאנו מחשיבים את המעשה עצמו כמו תוצאה, וכיון דאיכא בהאי תוצאה חסרון שנעשית ע\"י שנים, היינו, מה שכח אחד הוא רק חלק מגורמי המעשה, יש בזה שני חלקים, האחד, במעשה כולו. והשני, בכל חלק מהמעשה."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"363\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">48\u003c/sup>\u003cspan class=\"ca\" data-c=\"363\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">והחלק הראשון אין זה גדר בכח עצמו, אלא בגדר מעשה האדם, דהרי אין משמעות בכח הפועל בכל המעשה, שכל רגע ורגע יש להחשיבו ככח נפרד, והיינו, מה שנחשב המעשה של האדם, כיון שנעשה מכח שלו, וכיון שכך יש לחשב זה ביחס לאדם, היינו, מה נחשב לאדם מעשה שלו, וכיון שיש בכוחו לעשות המעשה כולו, הרי שלא עשה אלא מקצתו.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"364\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">49\u003c/sup>\u003cspan class=\"ca\" data-c=\"364\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">אבל גדר החלק השני, היינו, כל חלק מהמעשה, אין זה גדר באדם אלא בכח, ואין משמעותו ביחס לכלל המעשה, שאין זה מגדרי כח, אלא כל חלק נבחן לעצמו וביחס להיותו כח הפעולה.\u003c/span>"}, {"s": "h7", "h": "מחלוקת ר\"י ור\"ש במיעוט בעשותה - מיעוט באדם לעומת מיעוט בכח עצמו גבי מלאכת שבת"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"365\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">50\u003c/sup>\u003cspan class=\"ca\" data-c=\"365\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וא\"כ יבואר דכיון דלר\"י גדר המיעוט הוא ביחס לאדם, ומה שיחשב מעשה שלו, הרי שאין חסרון באין יכולים מה שאין בכח לעשות כל חלק מהמעשה, דאין זה גדר באדם. אבל לר\"ש דהמיעוט הוא ביחס לכח עצמו, בהכרח דפירושו הוא שיש חסרון בכח שאינו ראוי לעשות את המעשה לבדו, ואין זה גדר בכלל המעשה, וזה שאמר בעשותה, היינו, שאין זה מיעוט לגבי נפש אחת, אלא המיעוט הוא ביחס למעשה שלה, היינו, גדר כח שלה במעשה, ובזה לא יועיל מה שנחשב המעשה דאדם בכל העשייה משום דדרכו בכך, כיון דיש מיעוט בכח, ואין כח שלו נחשב להגדיר המעשה.\u003c/span>"}, {"s": "p", "h": "ונמצא גדר מעשה מלאכה לר\"ש כך, דהתוצאה החשובה מגדירה את המעשה כאסור, והמעשה האסור כולו, וכח שפועל במעשה זה, מגדיר את חלקי המעשה כשל האדם, והאדם מגדיר את המעשה כולו כאחד."}, {"s": "h7", "h": "דקדוק לישנא דקרא בפרשת חטאת - נפש אחת, מעם הארץ, ובעשותה, כשלושה מיעוטים נפרדים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"366\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">51\u003c/sup>\u003cspan class=\"ca\" data-c=\"366\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ואחר כל זה נראה לדקדק לשון הפסוק דכתיב נפש אחת תחטא בשגגה מעם הארץ בעשותה, דהנה מיעוט דנפש, אין זה מיעוט במעשה דשנים, רק דהפסוק איירי אחטא דחד, והיינו, שדין חטאת הנ\"ל נאמר על כל יחיד ויחיד, ואין לחייב שתי נפשות בחטאת אחת ומיעוט דאחת הוא מיעוט דנפש, היינו, דאין חטא שלה חלק מחטא דשנים. ומילות מעם הארץ הבאים אחר תחטא בשגגה, דלכאורה אין זה מקומם, דאם האי מעם קאי אאחת, הוה ליה למימר אחת מעם הארץ, ומשמע דהוא קאי גם על תחטא בשגגה, והיינו, דנפש אחת תחטא בשגגה מעם הארץ שחטא, או שלא חטא. ומיעוט דבעשותה, היינו, בעשייה שלה דהוה ליה למיכתב בעשות או בעשיית. והנה לר\"ש ולר\"י איכא שלושה מיעוטים הנ\"ל, ולר\"מ נפש אחת אין הם אלא מיעוט אחד, ואיכא תרי מיעוטים.\u003c/span>"}], "comments": [{"id": "1017", "n": 1, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-220 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (16 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. עשייה חלקית דעוקר ומניח - חילוק מכתיבה שבה כל מעשה יוצר דבר מוגמר בפני עצמו\u003c/p>\u003cp>2. בירור בגדר עשייה חלקית דזה עוקר וזה מניח לשם מלאכה\u003c/p>\u003cp>3. דיני פטור וחיוב דמלאכות שבת הנלמדים מפרשת חטאת\u003c/p>\u003cp>4. חילוק גדר זה בהוצאה משאר מלאכות\u003c/p>\u003cp>5. ביאור חילוק הנ\"ל לפמשנ\"ת בגדר הוצאה כמעשה שינוי\u003c/p>\u003cp>6. פרשת חטאת כמגדירה את גדרי המעשה המחייב בשבת\u003c/p>\u003cp>7. פיצול מעשה הוצאה בין שניים – האם שם מלאכה קיים\u003c/p>\u003cp>8. פטור שנים – חסרון ייחוס או חסרון מעשה\u003c/p>\u003cp>9. צירוף שיעורים בהוצאה – מעשה מתמשך או חפצא מצטבר\u003c/p>\u003cp>10. פטור עוקר ומניח – מיעוט מקרא או חסרון מלאכה\u003c/p>\u003cp>11. בירור בגדר עשייה חלקית דזה עוקר וזה מניח לשם מלאכה - חילוק מכתיבה שאין בה חסרון בהוצאה כשלנפרד, כי בכתיבה כל מעשה יוצר דבר מוגמר משלו וחסרונו רק בחשיבות התוצאה\u003c/p>\u003cp>12. חילוק גדר זה בהוצאה משאר מלאכות - הוכחה מכותב שאחזו הקולמוס יחד שהפטור בשנים אינו גדר מיוחד להוצאה, אלא שבכתיבה כל אחד יוצר דבר מוגמר בפני עצמו, ורק בהוצאה היתה הו\"א לחייב\u003c/p>\u003cp>13. פיסקה:  פרשת חטאת כמגדירה את גדרי המעשה המחייב בשבת\u003c/p>\u003cp>14. פיסקה:  פיצול מעשה הוצאה בין שניים – האם שם מלאכה קיים\u003c/p>\u003cp>15. פיסקה:  פטור שנים – חסרון ייחוס או חסרון מעשה\u003c/p>\u003cp>16. פיסקה:  פטור עוקר ומניח – מיעוט מקרא או חסרון מלאכה\u003c/p>"}, {"id": "325", "n": 2, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0787 | תיקון ציטוט הפסוק | חומרה: בינונית נוסח הפסוק בויקרא ד, כז הוא „בעשותה אחת ממצות ה׳ אשר לא תעשינה ואשם”. בטקסט נכתב „בעשתה” ללא וי״ו. יש לתקן ל„בעשותה” אם אין כאן נוסח מכוון, ולהוסיף מראה מקום בסיום הציטוט. רצוי גם לאחד את צורת כתיבת שם ה׳ לאורך החיבור.\u003c/p>"}, {"id": "326", "n": 3, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0788 | מפת המיעוטים בשבת צג ע״א – להציג לפי כל תנא | חומרה: קריטית לבירור הגמרא בשבת צג ע״א מחלקת את שלושת המיעוטים שבפסוק באופן שונה לרבי שמעון, רבי יהודה ורבי מאיר. לרבי שמעון: זה עוקר וזה מניח; זה יכול וזה יכול; זה אינו יכול וזה אינו יכול. לרבי יהודה: שני המיעוטים הראשונים, והמיעוט השלישי נדרש ליחיד שעשה בהוראת בית דין. לרבי מאיר: שני מיעוטים בלבד – זה עוקר וזה מניח ויחיד בהוראת בית דין. יש להציג טבלה מדויקת של לשון הגמרא לפני ניתוח המחבר, ולהבחין בין דין „עשה מקצתה” לבין דין „שנים שעשאוה”. מקור: שבת צג ע״א.\u003c/p>"}, {"id": "327", "n": 4, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0789 | תוספות שבת צג ע״א – להפריד את לשון הראשונים מן ההסבר העצמאי | חומרה: גבוהה תוספות שבת צג ע״א, ד״ה „חד למעוטי זה עוקר וזה מניח”, אכן מביאים כתיבת אות אחת על ידי אדם אחד ואות שנייה על ידי חברו, ומסבירים שהפסוק נצרך בהוצאה משום שהיינו עשויים לחשוב שחיוב הוצאה והכנסה חל גם בלא הנחה. יש לציין את דיבור המתחיל המדויק ולהפריד בין דברי תוספות לבין הסבר המחבר שההבדל תלוי ב„דבר המוגמר”. יש לבחון גם את שיעור שתי אותיות בכתיבה, כדי שלא תשתמע מסקנה שאות אחת לבדה היא שיעור החיוב.\u003c/p>"}, {"id": "328", "n": 5, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-175 | חומרה: גבוהה | קטגוריה: אחזו קולמוס — להפריד דוגמה של שניים שעשאוה ממחלוקת התנאים. הכותרת מחברת בין דוגמת שניים שאוחזים בקולמוס לבין מחלוקת רבי מאיר וחכמים ב״זה יכול וזה יכול״. יש להבהיר אם הקולמוס הוא דוגמה עצמאית לשותפות במעשה אחד, או שהוא מובא כראיה ישירה לשיטת תנא מסוים. הרמב״ם (הלכות שבת א, טו) מביא את אחיזת הקולמוס כדוגמה לשניים שעשאוה יחד, ואילו הסוגיה בשבת צג ע״א מחלקת את דיני התנאים לפי יכולת כל אחד לבצע את המלאכה לבדו. תוספות שם מדגישים שגם ״אינו יכול״ נקבע לפי אופן נשיאת הקורה בפועל, ולא רק לפי כוחו הכללי של האדם. לכן יש לציין מהי יכולת כל אחד במקרה הקולמוס ומהו מקור ההשוואה למחלוקת התנאים, כדי שלא ייראה שהדוגמה כשלעצמה מכריעה את שיטת רבי מאיר או חכמים.\u003c/p>"}, {"id": "329", "n": 6, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0790 | שניים האוחזים בקולמוס – לדייק את המקרה והמקור | חומרה: גבוהה ההשוואה בין שניים שאוחזים יחד בקולמוס לבין שניים שעקרו/הניחו בהוצאה דורשת מקרה מדויק. האם שניהם אוחזים באותו קולמוס וכותבים יחד, האם כל אחד כותב אות נפרדת, או שהאחד מסייע בהחזקת הכלי? יש לציין את מקור הדין ואת שיטת רבי מאיר/חכמים במדויק. אין להסיק מדין זה לבדו שכל אחד עושה „מלאכה שלמה” בלי לבדוק מהו שיעור הכתיבה ומהי תרומתו של כל אחד.\u003c/p>"}, {"id": "330", "n": 7, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-176 | חומרה: גבוהה | קטגוריה: הוצאה כשינוי מצב — להגדיר מה ייחודי במלאכה זו. הגדרת הוצאה כמעשה שחשיבותו בשינוי מצב החפץ היא חידוש מושגי של המחבר, ולא לשון מפורשת של תוספות בשבת צג ע״א. תוספות מסבירים מדוע נדרש מיעוט מיוחד לזה עוקר וזה מניח: היה מקום לחשוב שבהוצאה ובהכנסה מתחייבים אף בלא הנחה. מכאן עדיין לא מוכח שכל מעשה ההוצאה הוא יחידה אחת משום שהוא שינוי מצב של חפץ. יש להגדיר מהו השינוי המדויק — שינוי רשות, שינוי מקום או שינוי יחס החפץ לרשות — ולהסביר מדוע הוא שונה ממלאכות אחרות שגם בהן משתנה מצב החפץ, כגון בורר. יש להציג את הסבר המחבר כהצעה המרחיבה את דברי תוספות, ולא כפירוש המפורש בדבריהם.\u003c/p>"}, {"id": "331", "n": 8, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0791 | צירוף תוצאה לעומת ייחוס מעשה – שלוש שאלות נפרדות | חומרה: גבוהה הפסקה נעה בין צירוף שני חצאי שיעור של אותו אדם, צירוף שני חלקי מלאכה של שני אנשים, והחשבת התוצאה הסופית כמעשה של כל אחד. יש להפריד בין שלושת המקרים, משום שהדין של צירוף שיעורים אינו מוכיח בהכרח צירוף אחריות של שני עושי מעשה. לכל אחד יש להביא מקור ונפקא־מינה נפרדים.\u003c/p>"}, {"id": "1018", "n": 9, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-221 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (19 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. המתבאר לפי\"ז בגדר פטור זה עוקר וזה מניח\u003c/p>\u003cp>2. ביאור דברי רש\"י בפטור הנ\"ל דליכא חד דמסייע בכולה\u003c/p>\u003cp>3. תוספת ביאור בגדר הנ\"ל בחילוק דיני נזיקין משבת\u003c/p>\u003cp>4. גדר חילוק ושיתוף גרימה בשניים במעשה ובמלאכה\u003c/p>\u003cp>5. בחילוק צירוף הנ\"ל דליתא גבי ד\"א דהעברה ברה״ר\u003c/p>\u003cp>6. מחלוקת רש״י ותוס’ בגדר פטור עוקר ומניח\u003c/p>\u003cp>7. “בעשותה” – מיעוט שנים או מיעוט מקצת מעשה\u003c/p>\u003cp>8. מסייע – חסרון מעשה או חסרון ייחוס חטא\u003c/p>\u003cp>9. שבת – חיוב על מעשה, נזיקין – על תוצאה\u003c/p>\u003cp>10. מעשה שיכול להיעשות ע״י יחיד – משמעותו לשניים\u003c/p>\u003cp>11. המתבאר לפי\"ז בגדר פטור זה עוקר וזה מניח - חילוק בין פטור על חצי מעשה לפטור על מסייע, והוכחה שעקירה והנחה כל אחת נושאת משמעות הוצאה שלמה בפני עצמה, ולכן היה מקום לחייב שניהם לולי המיעוט\u003c/p>\u003cp>12. ביאור דברי רש\"י בפטור הנ\"ל דליכא חד דמסייע בכולה - חסרון בעצם גרימת המעשה ולא בשם מלאכה, וביאור שגרימת מלאכות שבת אינה תלויה בבעלות על התוצאה אלא בשייכות מעשהו ליצירתה\u003c/p>\u003cp>13. תוספת ביאור בגדר הנ\"ל בחילוק דיני נזיקין משבת - חילוק בין חיוב הבא מלקיחת ממון הדורש גרימה בלעדית לחיוב הבא מביטול שביתה שאינו דורש כן, וביאור מדוע זה אינו יכול וזה אינו יכול לר\"י כדרך עשייתו\u003c/p>\u003cp>14. ביאור שקלא וטריא דגמ' לפמשנ\"ת - חילוק גרימת המעשה בפועל מחשיבות המעשה ביצירת המלאכה, וכשכל אחד עשה חצי מלאכה אין צריך פסוק נוסף כי חצי מלאכה אינה נחשבת אף כחצי שיעור\u003c/p>\u003cp>15. וכן דהא לגבי העברה ד\"א ברה\"ר - פשיטות שאין חיוב, וביאור שהפטור דזה עוקר וזה מניח אינו גדר במלאכה עצמה אלא במעשה, שאין הוצאה נחשבת נעשית מאליה, וע\"כ היה מקום לחייב מעשה גורם חצי מהמלאכה\u003c/p>\u003cp>16. פיסקה:  מחלוקת רש״י ותוס’ בגדר פטור עוקר ומניח\u003c/p>\u003cp>17. פיסקה:  מסייע – חסרון מעשה או חסרון ייחוס חטא\u003c/p>\u003cp>18. פיסקה:  שבת – חיוב על מעשה, נזיקין – על תוצאה\u003c/p>\u003cp>19. פיסקה:  מעשה שיכול להיעשות ע״י יחיד – משמעותו לשניים\u003c/p>"}, {"id": "332", "n": 10, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-177 | חומרה: גבוהה | קטגוריה: זה עוקר וזה מניח — להפריד מדרש הפסוק, לשון רש״י והסבר הרשב״א. לפני קביעת גדר הפטור יש להפריד בין לשון הדרשה, פירוש רש״י והסבר הרשב״א. רש״י מפרש ״האי קעביד פלגא והאי פלגא וליכא חד דמסייע בכולהו״; הרשב״א מנסח את עיקר הדרשה כ״העושה את כולה ולא העושה את מקצתה״, ומבאר שגם כאשר שניים השלימו יחד את המלאכה, אין אחד מהם עושה את כולה לבדו. בהמשך הרשב״א מבחין בין שניים שכל אחד מהם עושה מעשה הנצרך למלאכה לבין מי שאינו אלא מסייע למי שיכול לעשותה לבדו. יש לבחון אם המחבר מציג מחלוקת ממשית בין רש״י לתוספות, או שמא הוא מציע חלוקה מושגית נוספת על דבריהם; אין להעמיד את כל הפער רק על הביטוי ״חצי מעשה״.\u003c/p>"}, {"id": "333", "n": 11, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0792 | לשון רש״י „פלגא” – יש להציג את ההסבר המלא | חומרה: גבוהה רש״י בשבת צג ע״א מסביר את המיעוט „זה עוקר וזה מניח”: „דהאי קעביד פלגא והאי פלגא וליכא חד דמסייע בכולהו”. יש להביא את הלשון המדויקת ולנתח את שני רכיביה: כל אחד עשה מחצית, ואין אחד המסייע בכל שלבי המלאכה. תוספות באותו מקום מציגים את ההקשר של הוצאה לעומת כתיבה. לפני שקובעים שיש מחלוקת בין רש״י לתוספות, יש להראות מה בדיוק כל אחד מבאר והאם הם עוסקים באותו מישור.\u003c/p>"}, {"id": "334", "n": 12, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0793 | „גרימה” בשבת – להבחין בין סיוע, כוחו ושותפות | חומרה: גבוהה הפסקה מציעה כלל רחב לגבי גרימה במלאכות שבת. יש להבחין בין כוחו של אדם, כוח טבעי (כגון רוח), מסייע שאינו יכול בפני עצמו, ושותפות של אדם נוסף. „מסייע אין בו ממש” בשבת צג ע״א נאמר בהקשר מסוים, ואין להרחיבו לכל סוגי הגרימה ללא מקור. מומלץ להגדיר את סוג הגרימה הנידון בכל דוגמה, ולנסח את המודל של המחבר כהצעה עד שייבדקו החריגים.\u003c/p>"}, {"id": "335", "n": 13, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0794 | ההשוואה לנזיקין – לסייג ולא להכליל | חומרה: גבוהה ההשוואה בין „זורה ורוח מסייעתו” לדיני נזיקין צריכה להיות תחומה למקרה ולמקור. הביטוי מופיע בבבא קמא ס ע״א בהקשר של רוח המסייעת למעשה הזורה; יש לבדוק מה בדיוק נאמר שם ומה נלמד ביחס לשבת. אין לנסח כלל שלפיו בנזיקין תמיד נדרש גורם יחיד ובשבת די בשייכות חלקית, בלי להביא דוגמאות נגדיות ודיני גרמא/שותפים. יש להבחין בין ייחוס סיבתי, ייחוס הלכתי של מעשה, וחיוב ממוני.\u003c/p>"}, {"id": "336", "n": 14, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-178 | חומרה: גבוהה | קטגוריה: מסייע — להבחין בין עזרה שולית לשותף שבלעדיו אין המלאכה. בסוגיית שבת צג ע״א ״מסייע אין בו ממש״ נאמר בדיון על זה יכול וזה אינו יכול: רב חסדא מחייב את היכול ופוטר את מי שאינו יכול, ורב המנונא מבקש לחייב גם את המסייע. אין להעתיק את דין המסייע למקרה של זה אינו יכול וזה אינו יכול, שבו שניהם נצרכים לעשיית המלאכה ואינם רק מסייע ועיקר. הרשב״א מחדד ששני אנשים שכל אחד מהם עושה מעשה הנצרך למלאכה אינם דומים למסייע שאינו יכול לעשות את המלאכה לבדו. לכן יש להגדיר אם ״המסייע״ בפסקה הוא שותף הכרחי, אדם שתרומתו שולית, או מי שאינו יכול לבצע את המלאכה לבדו אך בלעדיו אין היא נעשית; ורק לאחר מכן ניתן לקבוע אם דברי רש״י או שיטת רבי יהודה מחייבים אותו.\u003c/p>"}, {"id": "337", "n": 15, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-179 | חומרה: גבוהה | קטגוריה: גרימת המעשה — מבחן נגד־עובדתי אינו בהכרח ייחוס הלכתי. הטענה שאם אחד יפסיק את פעולתו השני יצטרך להגביר את פעולתו מוכיחה תלות עובדתית מסוימת בין המשתתפים, אך אינה מוכיחה כשלעצמה שכל אחד מהם נחשב כמי שגרם למעשה המלאכה כולו. יש להגדיר מהו מבחן הגרימה שהמחבר מציע: האם די בכך שאלמלא פעולת האדם השני לא היה המעשה נעשה באותה צורה, האם נדרשת תרומה הכרחית לתוצאה, או שמא נדרש שכל אחד יבצע חלק שאי אפשר להחליפו. בפרט יש להבחין בין זה יכול וזה אינו יכול, שבו היכול עשוי לבצע את המלאכה לבדו, לבין זה אינו יכול וזה אינו יכול, שבו המלאכה תלויה בשניהם. ההשוואה לנזיקין צריכה להיבנות לאחר הבחנה זו בין סיבתיות עובדתית לבין ייחוס הלכתי של מעשה.\u003c/p>"}, {"id": "338", "n": 16, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0795 | „מקצתה”, חצי שיעור וחצי מעשה – שלושה מושגים שונים | חומרה: קריטית לבירור כאן נטען שחצי מלאכה אינו מלאכה כלל, אך בפסקאות הקודמות נאמר שחצי שיעור עשוי להצטרף לתוצאה חשובה. יש להבחין בין חצי שיעור בכמות החפץ, חצי מעשה מבחינת שלבי ההוצאה, וחצי מלאכה מבחינת אחריות העושה. אם אלו שלושה מונחים שונים, יש להגדירם ולתת דוגמה לכל אחד. אם המחבר מתכוון לאותו מושג, נדרשת התאמה בין הטענות.\u003c/p>"}, {"id": "339", "n": 17, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0796 | שני מעבירים שתי אמות כל אחד – להגדיר את רצף ההעברה | חומרה: גבוהה הדוגמה של שני אנשים שכל אחד מעביר שתי אמות צריכה לפרט אם החפץ עובר מיד ליד ברציפות, אם יש הנחה באמצע, ואם הראשון מסיים את פעולתו לפני שהשני מתחיל. ללא הפרטים האלה לא ניתן להבחין בין צירוף שיעור של ארבע אמות, דין זה עוקר וזה מניח, ודין שניים שעשאוה. יש להביא מקור לדין המדויק או לסמן את הדוגמה כהיפותטית של המחבר.\u003c/p>"}, {"id": "1019", "n": 18, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-222 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (9 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. שנים שהוציאו יחד בעקירה והנחה - ביאור רש\"י שאין דרך לעשות המלאכה בשנים ליחיד\u003c/p>\u003cp>2. ביאור מש\"כ בפטור הנ\"ל שהוא ביחס למעשה\u003c/p>\u003cp>3. חילוק גדר הנ\"ל ביחס למעשה דכל חד\u003c/p>\u003cp>4. בירור בגדר הנ\"ל בעשו שנים יחד כל המעשה\u003c/p>\u003cp>5. חטאת – חיוב על מעשה מאוחד של יחיד\u003c/p>\u003cp>6. וממילא בזה עוקר וזה מניח אי לאו דאיתא לקרא היה לחייב שניהם - יסוד שהלימוד הוא ממראה מקום לחיוב הנעשה ע\"י אחד, וגדר הפטור הוא במעשה שגם עשיית המלאכה חלק מהחטא, ואין היחיד מתחייב ע\"י מעשה חבירו\u003c/p>\u003cp>7. ראה דלימוד זה אינו אלא ביחס לעשיית היחיד - יישום למיעוט יחיד שעשה בהוראת ב\"ד, וכן לגבי זה עוקר וזה מניח שמעשה זה אינו אלא ע\"י אחר ואין חשוב עשייה שלו\u003c/p>\u003cp>8. אבל בשנים שהוציאו יחד - חילוק מזה עוקר וזה מניח כי לכל אחד עשיית מעשה בכל המלאכה, וגדר החסרון הוא דין באחד לעומת שנים, וביאור רש\"י שגדר זה וזה יכולים משום שאין דרך לעשותו בשנים\u003c/p>\u003cp>9. פיסקה:  חטאת – חיוב על מעשה מאוחד של יחיד\u003c/p>"}, {"id": "340", "n": 19, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0797 | „יחיד שעשאה” מול „עשה מקצתה” – לאחד בזהירות | חומרה: גבוהה יש להבחין בין שלושה מיעוטים/דינים: יחיד שעשאה בהוראת בית דין; שנים שעשאוה; והעושה מקצתה. בסוגיית שבת צג ע״א כל אחד מקבל תפקיד שונה בחלוקת הפסוקים לפי רבי שמעון, רבי יהודה ורבי מאיר. אין להסיק מן הכלל שאדם אינו מתחייב על מעשה חברו שכל מקרה של שלבים שביצעו שני אנשים נכלל באותו מיעוט. מומלץ להציג תחילה את לשון הפסוקים והדרשות ואז להעמיד את המודל המושגי.\u003c/p>"}, {"id": "341", "n": 20, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-180 | חומרה: קריטית | קטגוריה: ״אין היחיד מתחייב על ידי מעשה חברו״ — האם המחבר מרחיב עיקרון של חטאת לכל התורה. ההרחבה כאן מן הכלל ״אין היחיד מתחייב על ידי מעשה חברו״ אל כלל כל עבירות החטאת דורשת הפרדה בין עיקרון כללי של ייחוס החטא לעושה לבין הדרשה המסוימת בשבת צג ע״א. הגמרא דורשת את ״בעשותה״ ומונה מיעוטים נפרדים ל״זה עוקר וזה מניח״, ״זה יכול וזה יכול״ ו״זה אינו יכול וזה אינו יכול״ לפי שיטת רבי שמעון; אין להניח מכאן שכל חיוב חטאת בכל תחום דורש שהעושה יהיה יחיד בכל שלבי המעשה. הרשב״א מנסח את עיקר הדרשה ״העושה את כולה ולא העושה את מקצתה״, ומדגיש שגם כאשר המלאכה כולה נעשית בין שניהם, כל אחד עושה רק מקצתה. יש להבהיר אם המחבר מציע כלל כללי בדיני חטאת, או רק משתמש בכלל זה כדי להסביר את פטור שניים שעשאוה בשבת. כמו כן, יש להבחין בין ייחוס החטא, הגדרת שם המלאכה, ועצם גרימת התוצאה.\u003c/p>"}, {"id": "1020", "n": 21, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-223 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (8 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. הקושי בלשון רש\"י אין דרך בשנים - אמאי מחייבינן בזה יכול וזה אינו יכול\u003c/p>\u003cp>2. גדר זה יכול וזה יכול - מעשה האחיזה בפועל לעומת אי השביתה בחיוב כל אחד\u003c/p>\u003cp>3. בירור דברי רש\"י בחסרון דזה וזה יכולים דאין דרך בשנים\u003c/p>\u003cp>4. בירור לישנא דקרא בגדר מעשה המחייב\u003c/p>\u003cp>5. ביאור גדר האיסור ומשמעותו ביחס לפטור הנ\"ל\u003c/p>\u003cp>6. “זה יכול וזה יכול” – פטור מצד עודפות\u003c/p>\u003cp>7. אך זה קשה שהרי בזה יכול וזה אינו יכול חייב זה שיכול לכולי עלמא - וקושי בעיקר דברי רש\"י אמאי אין דרכו בכך אמור ביחס לשני אלה ולא ביחס לעולם, ותמיהה שהיה מסתבר לחייב דוקא את שאינו יכול\u003c/p>\u003cp>8. ועתה נשוב לגדר זה יכול וזה יכול - שני גדרים נפרדים, האחיזה המשותפת בפועל המגדירה שנעשה בשנים, וגדר אי השביתה שבחיוב כל אחד בנפרד שאינו תלוי במעשה בפועל\u003c/p>"}, {"id": "342", "n": 22, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-181 | חומרה: גבוהה | קטגוריה: ״אין דרך לעשותו בשניים״ — להפריד בין דרך המלאכה לבין מעמד המסייע. הקושיה על רש״י מניחה שהביטוי ״אין דרך לעשותו בשניים״ מגדיר את מעמד שני המשתתפים בכל המקרים. אולם יש להבחין בין ״זה יכול וזה יכול״, שבו כל אחד עושה את כולה ורש״י מסביר שאין דרכה להיעשות בשניים, לבין ״זה יכול וזה אינו יכול״, שבו רש״י אומר שהיכול עשה את כולה והאחר אינו אלא מסייע שאין בו ממש. תוספות מוסיפים ש״אינו יכול״ אינו נמדד לפי כוחו הגופני המופשט של האדם: גם אדם בעל כוח רב עשוי להיחשב אינו יכול כאשר אופן אחיזת הקורה מחייב את עזרת חברו. לפיכך יש להפריד בין דרך עשיית המלאכה בשניים לבין השאלה אם תרומת השני היא מעשה עצמאי או סיוע בלבד. כך ניתן לברר את הקושיה בלי לייחס לרש״י שהדרך נקבעת לפי היכולות האישיות של זוג האנשים המסוים.\u003c/p>"}, {"id": "343", "n": 23, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-182 | חומרה: גבוהה | קטגוריה: תוצאה משותפת ושתי חטאות — לחדד את יחידת החיוב. הטענה שהגדר הוא בשניהם יחד, ובה בעת ״שניהם חייבים חטאת נפרדת״, מחייבת להבחין בין תוצאה פיזית אחת, מעשה משותף ויחידת החיוב של כל אדם. אם היעדר השביתה נקבע על ידי התוצאה המשותפת, מדוע אותה תוצאה מחייבת שתי חטאות נפרדות? האם כל אחד מוגדר כמי שעשה את אותה מלאכה עצמה, או שכל אחד חטא בעשייה עצמאית אף שהתוצאה הושגה בשיתוף? יש לבאר לאיזו שיטה בסוגיה מכוונת האמירה ״למאן דמחייב״, ומהו היחס בין המעשה המשותף לבין חיובו הפרטי של כל אחד. אין להניח ש״שניהם יחד״ ו״כל אחד לחוד״ הם שני ניסוחים לאותו גדר.\u003c/p>"}, {"id": "344", "n": 24, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0798 | „חציה” לעומת „מקצתה” – להגדיר קריטריון ממצה | חומרה: גבוהה ההבחנה המוצעת היא שבזה עוקר וזה מניח המלאכה עצמה מחולקת לשני מעשים ולכן כל אחד עשה „חציה”, ואילו בשניים האוחזים כל אחד עשה חלק מכל המלאכה ולכן עשה „מקצתה”. זהו חילוק עיוני חשוב, אך יש להגדיר מבחן חד: האם החלוקה היא לפי שלבי פעולה נבדלים, לפי תרומה סיבתית, או לפי היקף המעשה של כל אדם. רצוי להציג טבלה של ארבעת המקרים: זה עוקר וזה מניח; זה יכול וזה יכול; זה אינו יכול וזה אינו יכול; זה יכול וזה אינו יכול.\u003c/p>"}, {"id": "1021", "n": 25, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-224 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (3 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. דעת ר\"מ בשנים שהיו אוחזים - כח בכל המעשה וממילא די בכוונתו כמו רוח מסייעתו\u003c/p>\u003cp>2. דעת ר\"י בזה אינו יכול - תלות הדדית יוצרת מעשה אחד משא\"כ ביכולים שעושים בנפרד\u003c/p>\u003cp>3. המשך ביאור דעת ר\"ש - צריכות הכוונה ההדדית עושה את המלאכה למעשה שנים ולא מעשה יחיד, אך כשאחד יכול והשני אינו יכול אין הראשון צריך לכוונת חבירו ונחשב מעשה שלו לבד\u003c/p>"}, {"id": "345", "n": 26, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0799 | זורה ורוח מסייעתו – להפריד מקור מן הסברה על כוונת הרוח | חומרה: גבוהה הביטוי „זורה ורוח מסייעתו” מופיע בבבא קמא ס ע״א בהקשר של ייחוס פעולת הרוח למעשה האדם. יש לציין אם המחבר נשען על אותה סוגיה בלבד או גם על מקורות בשבת. הטענה שבאדם אחר נדרשת כוונה עצמאית, ואילו ברוח די בכוונת הזורה, היא חידוש שדורש ביסוס: יש להסביר מהו ההבדל בין כוח טבעי לבין כוח של אדם אחר, ומדוע כוונת הראשון מייחסת אליו את פעולת הרוח אך אינה מייחסת אליו את פעולת חברו.\u003c/p>"}, {"id": "346", "n": 27, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-183 | חומרה: גבוהה | קטגוריה: דעת רבי מאיר — מה פירוש ״כוח בכל המעשה״ והאם יש לכך מקור. הייחוס של ״כוח בכל המעשה״ לכל אחד מן האוחזים, כך שכוונת האחד יכולה להקיף גם את מעשה חברו, אינו מפורש בדברי רבי מאיר או בסוגיית זורה ורוח מסייעתו. בשבת צג ע״א הגמרא מחלקת לפי יכולת כל אחד, ורש״י מסביר שב״זה יכול וזה יכול״ כל אחד עושה את כולה, אך אין בדבריו אמירה שכוחו של כל אחד כולל את מעשה חברו. יש להגדיר מה פירוש ״כוח בכל המעשה״: אחיזה פיזית המשתתפת בכל התהליך, יכולת לבצע את המלאכה לבדו, או ייחוס הלכתי של חלק חברו למעשהו. לאחר מכן יש להראות כיצד הגדרה זו מסבירה דווקא את דעת רבי מאיר. בבבא קמא ס ע״א רש״י תולה את דין הרוח בכך שנתקיימה מחשבת הזורה והוא מרוצה בסיועה; אין בכך כשלעצמו מקור לכך שכוונת אחד מן האוחזים מייחסת אליו גם את פעולת חברו.\u003c/p>"}, {"id": "347", "n": 28, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0800 | שיטת רבי יהודה בשניים שאינם יכולים – מקור לעומת פירוש המחבר | חומרה: גבוהה בסוגיית שבת צג ע״א רבי יהודה מחייב כשאין אחד יכול להוציא לבדו ושניים עשו יחד, ופוטר כשכל אחד יכול. ההסבר שהמחבר מציע – תלות הדדית בכוונת השני יוצרת „מעשה אחד” – אינו לשון מפורשת בגמרא. יש לסמן זאת כחידוש המחבר, להביא את לשון רש״י ותוספות, ולהראות כיצד המודל מסביר את חיוב שניהם ואת הפטור כשכל אחד יכול בפני עצמו.\u003c/p>"}, {"id": "348", "n": 29, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-184 | חומרה: גבוהה | קטגוריה: דעת רבי שמעון — תלות בכוונת השני לעומת תלות במעשהו. הסבר דעת רבי שמעון בכך שהמלאכה נעשית מכוח ״כוונת שנים״ דורש להפריד בין תלות פיזית במעשה חברו לבין תלות בכוונתו. ייתכן שהאדם השני נצרך מבחינה פיזית אף שאינו מכוון לאותו יעד; ולהפך, שניים יכולים לכוון יחד אך כל אחד יכול לבצע את המלאכה לבדו. הרשב״א מדגיש שב״זה אינו יכול וזה אינו יכול״ הטעם לחיוב לשיטת רבי יהודה הוא שהמלאכה כולה תלויה בכל אחד, ולא מפני שכל אחד רק מסייע לחברו. לכן יש להראות מדוע דעת רבי שמעון מבוססת דווקא על איחוד הכוונות ולא על תלות המעשה או על דרשת ״בעשותה״. יש גם להסביר כיצד המודל מתיישב עם ״זה יכול וזה אינו יכול״, שבו לפי המחבר היכול אינו זקוק לכוונת המסייע.\u003c/p>"}, {"id": "1022", "n": 30, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-225 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (11 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. ספק הגמרא בז\"י וז\"י לר\"מ - חילוק בין חיוב כל אחד בנפרד לחיוב הנשען יחד\u003c/p>\u003cp>2. ביאור הוכחת הגמ' מהא דאין צריך שיעור זיבה לזה וכו'\u003c/p>\u003cp>3. בירור בשייכות גדר מסייע דטומאה להכא\u003c/p>\u003cp>4. ביאור מה דלא בעו לה אלא בזה וזה יכולים ולר\"מ\u003c/p>\u003cp>5. שיעור בטומאה וטביחה – צירוף חפצי או מעשי\u003c/p>\u003cp>6. מקור הספק – בין חסרון מעשה לחסרון ייחוס\u003c/p>\u003cp>7. ביאור שייכות גדר מסייע דטומאה להכא - הדימוי בין המדרס לדריסה, שכשם שחשיבות המלאכה מגדירה את המעשה כאי שביתה כך טומאת הזב מגדירה את מעמידיה כמדרס\u003c/p>\u003cp>8. ביאור הוכחת הגמ' מהא דאין צריך שיעור זיבה לזה ולזה - שיעור כחשיבות תוצאה כמו שיעור גרוגרת, וכן לגבי טביחה שאינה גדר ממוני ולכן דין ד' וה' מגדיר מעשיהם כטביחה\u003c/p>\u003cp>9. בירור בהא דלא בעו לה אלא בזה וזה יכולים ולר\"מ - חילוק בין חיוב כל אחד בנפרד לחיוב שנשען על השני\u003c/p>\u003cp>10. פיסקה:  שיעור בטומאה וטביחה – צירוף חפצי או מעשי\u003c/p>\u003cp>11. פיסקה:  מקור הספק – בין חסרון מעשה לחסרון ייחוס\u003c/p>"}, {"id": "349", "n": 31, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-185 | חומרה: גבוהה | קטגוריה: ההכללה לכל דיני התורה — גבולות ההשוואה למדרס. המשפט ״לכל דיני התורה השייכים במעשה אין גדר במה שזה יכול לבד אם לא היה זה״ הוא הכללה רחבה מאוד. בסוגיית מדרס עצמה היכולת לעמוד על שלוש רגליים היא חלק מרכזי מן ההכרעה: במיטה נאמר שאינה יכולה לעמוד על שלוש, ואילו בבהמה נאמר שיכולה לעמוד על שלוש; הגמרא מביאה גם את דחיית רב יהודה מדיסקרתא, שלפיה אפשר שהסיוע יש בו ממש אלא שהרגל נעקרת לגמרי, ולאחר מכן דנה בזב המתהפך על חמישה ספסלים או פונדאות. רש״י מפרט כמה אופנים לקריאת המקרים ואף מציין נוסח/פירוש חלופי. אין להסיק מן ההשוואה למדרס כלל גורף שלפיו יכולת היחיד אינה רלוונטית בתחומים אחרים. יש לצמצם את הטענה או להראות מדוע בדיני טומאה מתקיים גדר שונה, ומהו בדיוק הצד השווה שהמחבר מבקש ללמוד.\u003c/p>"}, {"id": "350", "n": 32, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0801 | ההשוואה לטומאת מדרס – להציג את שלבי הסוגיה | חומרה: גבוהה הגמרא בשבת צג ע״א משווה את דין „מסייע אין בו ממש” לדיני מדרס ומשענת. יש להציג את לשון הברייתא ואת תפקיד כל מקרה: מיטה שאינה יכולה לעמוד על שלוש רגליים; בהמה שיכולה לעמוד על שלוש; והדיון אם הסיוע נחשב מעשה. לאחר מכן להסביר מהו הצד השווה שהמחבר מציע בין טומאה לשבת. אין לקבוע שה„תוצאה מגדירה את המעשה” היא מסקנת הגמרא עצמה; זהו ניסוח מושגי של המחבר.\u003c/p>"}, {"id": "351", "n": 33, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0802 | שיעור זיבה, גרוגרת וטביחה – לאחד רק לאחר בירור | חומרה: גבוהה הפסקה מצרפת שלושה דינים מתחומים שונים: שיעור גרוגרת במלאכת שבת, שיעור ראייה/זיבה בדיני טומאה, וחיוב ארבעה וחמישה בטביחה. יש להביא מראה מקום מדויק לכל אחד ולהבהיר מהו הצד השווה: האם מדובר בשיעור התוצאה, בהגדרת המעשה או במספר החיובים. בפרט, הטענה שטביחה אינה גדר ממוני אלא הגדרת מעשה דורשת מקור ודיון בדיני כפל וארבעה וחמישה.\u003c/p>"}, {"id": "352", "n": 34, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0803 | מדוע הספק נוגע לרבי מאיר – להציג את שלבי הראיה | חומרה: גבוהה ההסבר מדוע הגמרא מסתפקת רק ב„זה יכול וזה יכול” לפי רבי מאיר, ולא במקרה „זה אינו יכול וזה אינו יכול” לפי רבי יהודה, הוא ניתוח של המחבר. יש להציג תחילה את סדר השקלא וטריא בשבת צג ע״א ואת הראיה ממדרס/משענת, ואז להראות כיצד נובע מכך שהספק קשור לשיעור של כל אחד בנפרד. יש לסמן את החלוקה בין „מעשה כל אחד בנפרד” ל„מעשה של שניהם יחד” כמודל פרשני, אם אינה מפורשת בגמרא.\u003c/p>"}, {"id": "1023", "n": 35, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-226 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (7 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. ביאור חסרון דזה עוקר וזה מניח בתרתי\u003c/p>\u003cp>2. דקדוק לישנא דגמ' בחילוק גדר פטור דר\"י מדר\"מ\u003c/p>\u003cp>3. חילוק גדר תוצאה דמעשה שבת משאר איסורים וביחס לחיוב חטאת\u003c/p>\u003cp>4. איסור כחל על המעשה ולא על החפץ\u003c/p>\u003cp>5. ביאור חסרון דזה עוקר וזה מניח בתרתי - עשה מקצתה וחסרון מכח שכל אחד עשה חצי בלבד, ולר\"ש אין צריך לזה כלל כי המלאכה קיימת רק ע\"י שניהם\u003c/p>\u003cp>6. מסקנה שגדר מעשה שבת לגבי חטאת הוא מעשה האיסור ולא מעשה הגרימה - ומזה שהמיעוט דשנים אינו ביחס לגרימת תוצאה אלא ביחס למעשה עצמו, שנחשב חצי מעשה ולא חצי תוצאה\u003c/p>\u003cp>7. פיסקה:  איסור כחל על המעשה ולא על החפץ\u003c/p>"}, {"id": "353", "n": 36, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0804 | סיכום שני החסרונות ב„זה עוקר וזה מניח” | חומרה: גבוהה הסיכום מבחין בין חסרון „העושה מקצתה” לבין „עביד פלגא”. יש להבהיר אם אלו שני דינים מצטברים או שני הסברים חלופיים לפטור, ומה המקור לכל אחד בשיטות התנאים. רש״י בשבת צג ע״א מסביר „האי קעביד פלגא והאי פלגא וליכא חד דמסייע בכולהו”; יש לבדוק כיצד הסבר זה מתיישב עם ההבחנה שהמחבר בונה בין מקצתה לחציה.\u003c/p>"}, {"id": "354", "n": 37, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0805 | סדר הברייתא וייחוס הדעות – להביא נוסח מדויק | חומרה: גבוהה יש להביא את נוסח הברייתא/הסוגיה בשבת צג ע״א במלואו במידה הדרושה, ולציין היכן רבי יהודה מוסיף את החלוקה בין „יכול” ל„אינו יכול”. חשוב לבדוק אם „אומר את כל הדין מחדש” הוא תיאור של נוסח הברייתא או מסקנת המחבר מסדר דברי התנאים. יש להבחין גם בין „חייבין ופטורין” לבין „חייב/פטור” רק אם יש לכך משמעות הלכתית ולא הבדל סגנוני.\u003c/p>"}, {"id": "355", "n": 38, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0806 | שני גדרי מעשה – סיכום המחבר דורש מפת יחסים | חומרה: גבוהה הפסקה מסכמת מודל שבו התוצאה מגדירה את העושה כמבטל שביתה, אך המעשה עצמו נידון לפי דיני חטאת וכללי מעשה. יש להציג את שני הגדרים בטבלה: מה נחשב המעשה; מה נחשבת התוצאה; למי מיוחסת התוצאה; ומהו מקור הפטור/החיוב. יש להיזהר שלא לייחס לגמרא את המודל המלא, אלא להציגו כהצעת הסבר של המחבר לדרשות הפסוק ולמחלוקות התנאים.\u003c/p>"}, {"id": "1024", "n": 39, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-227 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (12 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. פטור קרא דחטאת בכח המעשה - מיעוט אחד ולא שנים נוגע לכח הפעולה במעשה שבת\u003c/p>\u003cp>2. ביאור גדר פטור חטאת שאינו מגדרי מעשה מלאכה\u003c/p>\u003cp>3. ביאור חיוב בזה יכול וזה אינו יכול ודל אחשיב מסייע\u003c/p>\u003cp>4. שני גדרים בעשיית כל חד במעשה הנעשה בשנים ובחשיבות תוצאתו לצירופם\u003c/p>\u003cp>5. חילוק גדר עשייה חלקית בגרימת תוצאה מכח המעשה\u003c/p>\u003cp>6. ביאור גדר פטור דזעוז\"מ ביחס לכח העושה במעשה\u003c/p>\u003cp>7. ביתר ביאור - שני גדרים אפשריים בעשיית כל חד במעשה הנעשה בשנים, חצי מעשה אסור או חלק מועט במעשה, וביאור שגדרים אלו לא שייכים במעשי גרימה, ורק בהוצאה שגדרה אינו גרימה שייך שכל אחד עשה מעשה איסור\u003c/p>\u003cp>8. אך גדר הפטור מקרא דחטאת אינו נוגע לגדר המיוחד של מלאכה - ולכן המיעוט דאחד ולא שנים אכן נוגע לכח במעשה, כשם שבגרימה כח הוא סיבה מספקת לתוצאה, כך בשבת כח הוא סיבה למעשה\u003c/p>\u003cp>9. חילוק גדר מעשה כגרימה מגדר כח דמעשה עצמו - בגרימה נדרשת סיבה מספקת ובכח דמעשה נדרש רק שהמעשה יחשב שלו, ומזה שדין שנים שעשו שייך אף בזורה ורוח מסייעתו\u003c/p>\u003cp>10. יסוד מה שיש בזה עוקר וזה מניח יותר סיבה להיכלל במיעוט דקרא - הוצאה עשויה משני מעשים ושני כוחות, ולכן המיעוט מגדיר כל אחד כחצי כח המעשה, בשונה מזורה ורוח מסייעתו שאין לרוח שם מעשה כלל\u003c/p>\u003cp>11. יישוב חיוב בזה יכול וזה אינו יכול - חסרון דמסייע אינו בגדר הכח אלא בכך שאינו נחשב כלל חלק מהמעשה האסור, וגדר המעשה כולו הוא במעשה הראשון בלבד והשני כרוח מסייעתו, ובזה לא נחלקו\u003c/p>\u003cp>12. יישוב מחלוקת ר\"י ור\"ש - בזה יכול וזה יכול ובזא\"י וזא\"י אין להעדיף כח אחד על השני, ולכן שניהם נחשבים כעושי המלאכה ואין חסרון דמסייע, וכן הדין אף לר\"מ בסיוע שאינו בגדר עביד פלגא\u003c/p>"}, {"id": "356", "n": 40, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0807 | תוצאת המלאכה לעומת חיובו האישי של כל עושה | חומרה: קריטית לבירור המשפט עובר מן הקביעה שהתוצאה הכוללת מגדירה את המעשה כמעשה מלאכה אל הקביעה שכל אחד מן המשתתפים „עשה מעשה איסור”. אלו שני שלבים שונים: אפשר שהצירוף יוצר מלאכה שלמה, אך עדיין יש לדון אם כל אחד נחשב עושה לעניין חיובו, ובאיזה שיעור של כוח או השתתפות. הדבר נחוץ במיוחד לאור המשך הפרק, שבו המחבר עצמו מבחין בין „שם מעשה” לבין ייחוסו לאדם. מומלץ לנסח כאן: התוצאה עשויה להגדיר את המעשה המשותף כמלאכה; שאלת ייחוס המעשה לכל אחד תתברר לפי דיני „שנים שעשאוה”.\u003c/p>"}, {"id": "357", "n": 41, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-186 | חומרה: גבוהה | קטגוריה: ״אחד ולא שנים״ — המקור המדויק למעבר ממיעוט בפסוק לגדר כוח המעשה. המעבר מן המיעוט שבפסוק אל הקביעה ש״אחד ולא שנים״ הוא גדר בכוח המעשה הוא חידוש פרשני, ויש להבחין בינו לבין לשון הסוגיה בשבת צג ע״א. הגמרא מפרטת כיצד רבי שמעון דורש שלושה מיעוטים מן ״נפש אחת... בעשותה״, ומקצה אותם למקרים מסוימים; רבי יהודה ורבי מאיר מקצים את המיעוטים באופן שונה. הרשב״א מפרש את עיקר הדרשה ״העושה את כולה ולא העושה את מקצתה״, ואף על פי כן עשיית המלאכה כולה בין שניים אינה הופכת כל אחד לעושה את כולה. יש לציין לאיזה מן המיעוטים אתה מתייחס כאן — לדרשת ״בעשותה״, ל״נפש/אחת״ או לניסוח ״יחיד שעשאה״ — ולהראות כיצד הוא מחייב להגדיר את הפטור כחסרון בכוח המעשה ולא כחסרון בגדר המלאכה. אין להציג את החלוקה המושגית כחלוקה מפורשת בגמרא בלי להעמיד את סדר הדרשות של כל תנא.\u003c/p>"}, {"id": "358", "n": 42, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0808 | זורה ורוח מסייעתו אינה דוגמה פשוטה לשני בני אדם שעשאוה | חומרה: גבוהה יש להיזהר מהמעבר מן הדין של „זורה ורוח מסייעתו” לדין „שנים שעשאוה”. בזורה האדם הוא העושה והרוח היא כוח טבע המסייע לו; אין כאן שני בני אדם שכל אחד מהם פועל במלאכה. המקור הקלאסי הוא שבת עג ע״א, ולצדו סוגיות כוח הרוח בבבא קמא ס ע״א. אפשר ללמוד מכאן שאין צורך שכל רכיבי הכוח יהיו בשליטת האדם, אך אין מכאן ראיה ישירה שהפטור של שניים שעשאוה חל באותו אופן. יש לנסח את ההשוואה כאנלוגיה מוגבלת ולהבהיר מהו ההבדל בין כוח טבעי לבין כוחו העצמאי של אדם אחר.\u003c/p>"}, {"id": "359", "n": 43, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0809 | עקירה והנחה – שני שלבים במלאכה או שני מעשים עצמאיים? | חומרה: גבוהה החידוש שמלאכת הוצאה „עשויה משני מעשים” טעון הגדרה מדויקת. עקירה והנחה הן שני שלבים הלכתיים נפרדים, אך עדיין יש לברר אם כל אחד מהם הוא מעשה עצמאי, או ששניהם רכיבים של מעשה הוצאה אחד. דברי תוספות שבת צג ע״א בעניין כתיבת שתי אותיות נוגעים לשאלה מתי ניתן לומר „שנים שעשאוה”; אין להציגם כראיה פשוטה לכך שהוצאה מורכבת משתי פעולות עצמאיות. כדאי להביא את לשון התוספות, להגדיר מהי „חלוקה במעשה”, ולהסביר מדוע החלוקה בעקירה והנחה שונה מחלוקת כתיבת שתי אותיות.\u003c/p>"}, {"id": "360", "n": 44, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0810 | „מסייע אין בו ממש” – קביעה הלכתית, לא שלילת התרומה העובדתית | חומרה: גבוהה במקרה „זה יכול וזה אינו יכול” יש להבחין בין תרומתו העובדתית של המסייע לבין ייחוס המעשה אליו לעניין חיוב. ייתכן שהשני מסייע בפועל, אך סיועו אינו מקבל מעמד עצמאי של מעשה מלאכה משום שהראשון יכול לעשותה לבדו. לכן „אין עליו שם מעשה כלל” הוא ניסוח חריף מדי אם כוונתו לשלול את עצם השתתפותו הפיזית. מומלץ להבהיר שהחסרון הוא במעמד ההלכתי של הסיוע, ולהביא את לשון הסוגיה בשבת צג ע״א ואת פירוש רש״י, בלי להפוך את הכלל לתיאור עובדתי.\u003c/p>"}, {"id": "361", "n": 45, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0811 | סימטריה בין שני העושים – נדרשת הבחנה בין „יכול” ל„אינו יכול” | חומרה: גבוהה הטענה שכאשר אין להעדיף אחד על חברו יש להחשיב את שניהם כעושי המלאכה מסבירה לכאורה את המקרה הסימטרי, אך יש להבחין בין „זה יכול וזה יכול” לבין „זה אינו יכול וזה אינו יכול”. בראשון כל אחד מסוגל לבצע את המלאכה לבדו; בשני אין לאף אחד כוח מספיק לבדו, ורק צירוף פעולותיהם משלים אותה. רבי יהודה ורבי שמעון נחלקים בשבת צג ע״א בשני המצבים, ואין די בטענת הסימטריה כדי להסביר את שניהם. רצוי להעמיד טבלה ובה: יכולת עצמאית, תרומה בפועל, ומעמד כל אחד לפי כל תנא.\u003c/p>"}, {"id": "1025", "n": 46, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-228 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (5 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. בירור בגדר כח העושה להחשיב המעשה כשלו\u003c/p>\u003cp>2. יסוד שני חסרונות אפשריים בעשיית כל חד במעשה הנעשה בשנים - האחד, במה שאין כוחו פועל כל המעשה, והשני, במה שאין די בכח שפעל, וזיהוי הגדרים בזה יכול וזה יכול ובזה אינו יכול וזה אינו יכול\u003c/p>\u003cp>3. הרחבת ביאור שני הגדרים - החלק הראשון גדר באדם ומה נחשב מעשה שלו, והחלק השני גדר בכח עצמו הנבחן לעצמו ביחס להיותו כח הפעולה בלבד\u003c/p>\u003cp>4. יישום ליישוב מחלוקת ר\"י ור\"ש - לר\"י המיעוט ביחס לאדם ולכן אין חסרון בזא\"י וזא\"י שאינו גדר באדם, ולר\"ש המיעוט ביחס לכח עצמו, וסיכום שלוש שכבות בגדר מלאכה לר\"ש - תוצאה מגדירה מעשה, כח מגדיר חלקים כשל אדם, ואדם מגדיר מעשה כאחד\u003c/p>\u003cp>5. דקדוק לישנא דקרא נפש אחת תחטא בשגגה מעם הארץ בעשותה - שלושה מיעוטים נפרדים, בנפש בהאם חטאה ובעשייתה, ולר\"מ נפש אחת אינה מיעוט ונשארים רק שניים\u003c/p>"}, {"id": "362", "n": 47, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0812 | שני סוגי חסרון בכוח – לקבוע מבחן שניתן ליישום | חומרה: גבוהה החלוקה בין חסרון בכך שאין כוחו פועל את כל המעשה לבין חסרון בכך שאין בכוחו די לפעול את המעשה היא בסיס חשוב להמשך. אולם יש להגדיר כיצד בוחנים „כוחו”: יכולת פיזית לבצע את כל הפעולה לבדו, שיעור הכוח שהפעיל בפועל, או תרומה סיבתית לתוצאה. אלה אינם בהכרח אותו נתון. לדוגמה, אדם המסוגל להרים לבדו אך בפועל אוחז רק בחלק מן המשקל – האם הוא „יכול” או שמודדים את כוחו בפועל? מומלץ לקבוע מבחן חד וליישם אותו בארבעת מצבי הסוגיה בשבת צג ע״א.\u003c/p>"}, {"id": "363", "n": 48, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-187 | חומרה: גבוהה | קטגוריה: כוח המעשה ביחס לאדם — יכולת שלא מומשה אינה כשלעצמה הוכחה לחסרון בייחוס. כאן אתה מגדיר את החלק הראשון כחסרון בייחוס המעשה לאדם: האדם יכול היה לעשות את כל המלאכה, אך בפועל עשה רק מקצתה, ולכן אין לייחס לו את המעשה כולו. יש להבחין בין שלושה נתונים: יכולת עצמאית לבצע את כל המלאכה; התרומה שבוצעה בפועל; והייחוס ההלכתי של התוצאה/המעשה לאדם. עצם העובדה שהאדם יכול היה לבצע יותר אינה מוכיחה לבדה שאין לייחס אליו את המעשה המשותף; נדרש להסביר מדוע היכולת שלא מומשה יוצרת חסרון בייחוס. כדאי להגדיר מבחן יישומי: האם בוחנים את יכולתו במצב הנתון, את האפשרות שהיה יכול לבצע את כל המעשה אילו פעל לבדו, או את היקף הכוח שהפעיל בפועל. זהו פירוט של מבחן הייחוס מעבר לבקשת ההגדרה הכללית שכבר הועלתה בהערה E-0812.\u003c/p>"}, {"id": "364", "n": 49, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-188 | חומרה: גבוהה | קטגוריה: ״כל חלק מהמעשה״ — להגדיר מה נחשב חלק עצמאי של כוח הפעולה. החלק השני נבחן בכל מקטע של המעשה בפני עצמו כ״כוח הפעולה״, אך המונח ״כל חלק״ עדיין אינו מוגדר. האם מדובר בשלבי המלאכה ההלכתיים (כגון עקירה והנחה), ברצף הזמן של הפעולה (כל רגע ורגע), בכמות/שיעור הכוח שהופעל, או ברכיבים פיזיים שונים של פעולה אחת? אלה חלוקות שונות, ותוצאתן עשויה להשתנות: פעולה רציפה אחת אפשר לחלק לרגעים בלי שכל רגע ייחשב מלאכה נפרדת; ולעומת זאת, עקירה והנחה הן שלבים הלכתיים מובחנים. יש לקבוע מהי יחידת החלוקה הרלוונטית, מדוע היא נחשבת כוח עצמאי, וכיצד אותו מבחן מיושם בשאר מלאכות שבת ולא רק בהוצאה.\u003c/p>"}, {"id": "365", "n": 50, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-06", "h": "\u003cp>S-20261106-189 | חומרה: גבוהה | קטגוריה: ״מיעוט באדם״ לעומת ״מיעוט בכוח״ — התאמת החידוש לסדר הדרשות של התנאים. החלוקה שאתה מציע — רבי יהודה ממעט את האדם ורבי שמעון ממעט את הכוח — היא מודל פרשני שאינו נאמר כך במפורש בסוגיה. בשבת צג ע״א הגמרא מקצה את מיעוטי הפסוק באופן שונה לפי התנאים: רבי שמעון דורש שלושה מיעוטים ומחלק אותם בין זה עוקר וזה מניח, זה יכול וזה יכול, וזה אינו יכול וזה אינו יכול; רבי יהודה מקצה את מיעוטיו אחרת, ובכללם יחיד שעשה בהוראת בית דין. יש להראות כיצד החלוקה המושגית שלך מתיישבת עם הקצאת המיעוטים בפועל ועם התוצאות בכל אחד ממצבי הסוגיה. בפרט, צריך להסביר מדוע לשיטת רבי שמעון יש חסרון בכוח גם כאשר שניים נצרכים למעשה, ומדוע אצל רבי יהודה החסרון מוגדר ביחס לאדם ולא ביחס לתרומתו בפועל. אין לייחס לגמרא את המינוח ״מיעוט באדם/בכוח״ בלי לסמן שזהו פירושו המחודש של המחבר.\u003c/p>"}, {"id": "366", "n": 51, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0813 | דרשת „מעם הארץ” – לא להעמיס על סדר המילים דרשה שאינה מפורשת | חומרה: קריטית לבירור הפירוש שלפיו „מעם הארץ” הוא מיעוט עצמאי הנוגע לשאלה אם היחיד חטא או לא חטא אינו עולה מאליו מפשוטו של הפסוק, שבו הביטוי מתאר את הנפש „מעם הארץ”. יש להראות מקור מדרשי או תלמודי מפורש לדרשה זו, או להציג אותה כחידוש דקדוקי של המחבר בלבד. בפרט, אין להסיק מן הסדר התחבירי שהביטוי מוסב גם על „תחטא בשגגה” במשמעות המוצעת בלי אסמכתה. מומלץ להביא את הפסוק המלא (ויקרא ד, כז) ולציין בנפרד את הדרשות המפורשות של שבת צג ע״א לכל אחד מן המיעוטים.\u003c/p>"}]};
